    51→/**
    52→ * Mesh generation (excluding triangulation) and processing.
    53→ * <p>
    54→ * Many of the methods within this class process an existing Delaunay
    55→ * triangulation; you may first generate such a triangulation from a shape using
    56→ * the
    57→ * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
    58→ * delaunayTriangulationMesh()} method.
    59→ * 
    60→ * @author Michael Carleton
    61→ * @since 1.2.0
    62→ */
    63→public class PGS_Meshing {
    64→
    65→	private PGS_Meshing() {
    66→	}
    67→
    68→	/**
    69→	 * Generates a shape consisting of polygonal faces of an <i>Urquhart graph</i>.
    70→	 * An Urquhart graph is obtained by removing the longest edge from each triangle
    71→	 * in a triangulation.
    72→	 * <p>
    73→	 * In practice this is a way to tessellate a shape into polygons (with the
    74→	 * resulting tessellation being in between a
    75→	 * {@link PGS_Triangulation#delaunayTriangulation(PShape) triangulation} and a
    76→	 * {@link micycle.pgs.PGS_Processing#convexPartition(PShape) partition}).
    77→	 * <p>
    78→	 * Note that this method processes a Delaunay triangulation. Process a shape
    79→	 * using
    80→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
    81→	 * delaunayTriangulationMesh()} first and then feed it to this method.
    82→	 * <p>
    83→	 * The <i>Urquhart graph</i> is a good approximation to the
    84→	 * {@link #relativeNeighborFaces(IIncrementalTin, boolean) <i>relative
    85→	 * neighborhood</i>} graph (having only about 2% additional edges).
    86→	 * 
    87→	 * @param triangulation     a triangulation mesh
    88→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
    89→	 *                          even if they should be removed according to the
    90→	 *                          urquhart condition
    91→	 * @return a GROUP PShape where each child shape is a single face
    92→	 * @since 1.1.0
    93→	 * @see #gabrielFaces(IIncrementalTin, boolean)
    94→	 */
    95→	public static PShape urquhartFaces(final IIncrementalTin triangulation, final boolean preservePerimeter) {
    96→		final HashSet<IQuadEdge> edges = PGS.makeHashSet(triangulation.getMaximumEdgeAllocationIndex());
    97→		final HashSet<IQuadEdge> uniqueLongestEdges = PGS.makeHashSet(triangulation.getMaximumEdgeAllocationIndex());
    98→
    99→		final boolean notConstrained = triangulation.getConstraints().isEmpty();
   100→
   101→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   102→			final IConstraint constraint = t.getContainingRegion();
   103→			if (notConstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   104→				edges.add(t.getEdgeA().getBaseReference());
   105→				edges.add(t.getEdgeB().getBaseReference());
   106→				edges.add(t.getEdgeC().getBaseReference());
   107→				final IQuadEdge longestEdge = findLongestEdge(t).getBaseReference();
   108→				if (!preservePerimeter || (preservePerimeter && !longestEdge.isConstrainedRegionBorder())) {
   109→					uniqueLongestEdges.add(longestEdge);
   110→				}
   111→			}
   112→		});
   113→
   114→		edges.removeAll(uniqueLongestEdges);
   115→
   116→		final Collection<PEdge> meshEdges = new ArrayList<>(edges.size());
   117→		edges.forEach(edge -> meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y)));
   118→
   119→		return PGS.polygonizeEdges(meshEdges);
   120→	}
   121→
   122→	/**
   123→	 * Generates a shape consisting of polygonal faces of a <i>Gabriel graph</i>. A
   124→	 * Gabriel graph is obtained by removing each edge E from a triangulation if a
   125→	 * vertex lies within a circle of diameter = length(E), centered on the midpoint
   126→	 * of E.
   127→	 * <p>
   128→	 * In practice this is a way to tessellate a shape into polygons (with the
   129→	 * resulting tessellation being reminiscent of shattering the shape as if it
   130→	 * were glass).
   131→	 * <p>
   132→	 * Note that this method processes a Delaunay triangulation. Process a shape
   133→	 * using
   134→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   135→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   136→	 * 
   137→	 * @param triangulation     a triangulation mesh
   138→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
   139→	 *                          even if they should be removed according to the
   140→	 *                          gabriel condition
   141→	 * @return a GROUP PShape where each child shape is a single face
   142→	 * @since 1.1.0
   143→	 * @see #urquhartFaces(IIncrementalTin, boolean)
   144→	 */
   145→	public static PShape gabrielFaces(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   146→		final HashSet<IQuadEdge> edges = new HashSet<>();
   147→		final HashSet<Vertex> vertices = new HashSet<>();
   148→
   149→		final boolean notConstrained = triangulation.getConstraints().isEmpty();
   150→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   151→			final IConstraint constraint = t.getContainingRegion();
   152→			if (notConstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   153→				edges.add(t.getEdgeA().getBaseReference()); // add edge to set
   154→				edges.add(t.getEdgeB().getBaseReference()); // add edge to set
   155→				edges.add(t.getEdgeC().getBaseReference()); // add edge to set
   156→				vertices.add(t.getVertexA());
   157→				vertices.add(t.getVertexB());
   158→				vertices.add(t.getVertexC());
   159→			}
   160→		});
   161→
   162→		final PointIndex<Vertex> tree = KDTree.create(2, (p1, p2) -> {
   163→			final double deltaX = p1[0] - p2[0];
   164→			final double deltaY = p1[1] - p2[1];
   165→			return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
   166→		});
   167→		vertices.forEach(v -> tree.insert(new double[] { v.x, v.y }, v));
   168→
   169→		final HashSet<IQuadEdge> nonGabrielEdges = new HashSet<>(); // base references to edges that should be removed
   170→		edges.forEach(edge -> {
   171→			final double[] midpoint = midpoint(edge);
   172→			final Vertex near = tree.query1NN(midpoint).value();
   173→			if (near != edge.getA() && near != edge.getB()) {
   174→				if (!preservePerimeter || (preservePerimeter && !edge.isConstrainedRegionBorder())) {
   175→					nonGabrielEdges.add(edge); // base reference
   176→				}
   177→			}
   178→		});
   179→		edges.removeAll(nonGabrielEdges);
   180→
   181→		final Collection<PEdge> meshEdges = new ArrayList<>(edges.size());
   182→		edges.forEach(edge -> meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y)));
   183→
   184→		return PGS.polygonizeEdges(meshEdges);
   185→	}
   186→
   187→	/**
   188→	 * Generates a shape consisting of polygonal faces of a <i>Relative neighborhood
   189→	 * graph</i> (RNG).
   190→	 * <p>
   191→	 * An RNG is obtained by removing each edge E from a triangulation if any vertex
   192→	 * is nearer to both vertices of E than the length of E.
   193→	 * <p>
   194→	 * The RNG is a subgraph of the {@link #urquhartFaces(IIncrementalTin, boolean)
   195→	 * urquhart} graph, having only slightly fewer edges.
   196→	 * 
   197→	 * @param triangulation     a triangulation mesh
   198→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
   199→	 *                          even if they should be removed according to the
   200→	 *                          relative neighbor condition
   201→	 * @return
   202→	 * @since 1.3.0
   203→	 */
   204→	public static PShape relativeNeighborFaces(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   205→		SimpleGraph<Vertex, IQuadEdge> graph = PGS_Triangulation.toTinfourGraph(triangulation);
   206→		NeighborCache<Vertex, IQuadEdge> cache = new NeighborCache<>(graph);
   207→
   208→		Set<IQuadEdge> edges = new HashSet<>(graph.edgeSet());
   209→
   210→		/*
   211→		 * If any vertex is nearer to both vertices of an edge, than the length of the
   212→		 * edge, this edge does not belong in the RNG.
   213→		 */
   214→		graph.edgeSet().forEach(e -> {
   215→			double l = e.getLength();
   216→			cache.neighborsOf(e.getA()).forEach(n -> {
   217→				if (Math.max(n.getDistance(e.getA()), n.getDistance(e.getB())) < l) {
   218→					if (!preservePerimeter || (preservePerimeter && !e.isConstrainedRegionBorder())) {
   219→						edges.remove(e);
   220→					}
   221→				}
   222→			});
   223→			cache.neighborsOf(e.getB()).forEach(n -> {
   224→				if (Math.max(n.getDistance(e.getA()), n.getDistance(e.getB())) < l) {
   225→					if (!preservePerimeter || (preservePerimeter && !e.isConstrainedRegionBorder())) {
   226→						edges.remove(e);
   227→					}
   228→				}
   229→			});
   230→		});
   231→
   232→		List<PEdge> edgesOut = edges.stream().map(PGS_Triangulation::toPEdge).collect(Collectors.toList());
   233→
   234→		if (preservePerimeter) {
   235→			return PGS.polygonizeEdgesRobust(edgesOut);
   236→		} else {
   237→			return PGS.polygonizeEdges(edgesOut);
   238→		}
   239→
   240→	}
   241→
   242→	/**
   243→	 * Generates a shape consisting of polygonal faces formed by edges returned by a
   244→	 * greedy sparse spanner applied to a triangulation.
   245→	 * 
   246→	 * @param triangulation     a triangulation mesh
   247→	 * @param k                 the order of the spanner. Should be at least 1.
   248→	 *                          Higher numbers collapse more edges resulting in
   249→	 *                          larger faces, until a single face remains
   250→	 * @param preservePerimeter whether to retain/preserve edges on the perimeter
   251→	 *                          even if they should be removed according to the
   252→	 *                          spanner condition
   253→	 * @return a GROUP PShape where each child shape is a single face
   254→	 * @since 1.3.0
   255→	 */
   256→	public static PShape spannerFaces(final IIncrementalTin triangulation, int k, final boolean preservePerimeter) {
   257→		SimpleGraph<PVector, PEdge> graph = PGS_Triangulation.toGraph(triangulation);
   258→		if (graph.edgeSet().isEmpty()) {
   259→			return new PShape();
   260→		}
   261→
   262→		k = Math.max(2, k); // min(2) since k=1 returns triangulation
   263→		GreedyMultiplicativeSpanner<PVector, PEdge> spanner = new GreedyMultiplicativeSpanner<>(graph, k);
   264→		List<PEdge> spannerEdges = spanner.getSpanner().stream().collect(Collectors.toList());
   265→		if (preservePerimeter) {
   266→			if (triangulation.getConstraints().isEmpty()) { // does not have constraints
   267→				spannerEdges.addAll(triangulation.getPerimeter().stream().map(PGS_Triangulation::toPEdge).collect(Collectors.toList()));
   268→			} else { // has constraints
   269→				spannerEdges.addAll(triangulation.getEdges().stream().filter(IQuadEdge::isConstrainedRegionBorder)
   270→						.map(PGS_Triangulation::toPEdge).collect(Collectors.toList()));
   271→			}
   272→		}
   273→
   274→		return PGS.polygonizeEdgesRobust(spannerEdges);
   275→	}
   276→
   277→	/**
   278→	 * Generates a (mesh-like) shape consisting of polygonal faces of the dual graph
   279→	 * of the given triangulation.
   280→	 * <p>
   281→	 * In practice, the resulting dual mesh has hexagonal-like cells.
   282→	 * <p>
   283→	 * Note that this method processes a Delaunay triangulation. Process a shape
   284→	 * using
   285→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   286→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   287→	 * <p>
   288→	 * If the input has been generated from a PShape, consider generating the
   289→	 * triangulation with <code>refinements > 1</code> for better dual mesh results.
   290→	 * 
   291→	 * @param triangulation a triangulation mesh
   292→	 * @return a GROUP PShape where each child shape is a single face
   293→	 * @since 1.2.0
   294→	 */
   295→	public static PShape dualFaces(final IIncrementalTin triangulation) {
   296→		// TODO SEE HOT: Hodge-Optimized Triangulations - use voronoi dual / HOT
   297→		final IncrementalTinDual dual = new IncrementalTinDual(triangulation);
   298→		final PShape dualMesh = dual.getMesh();
   299→		PGS_Conversion.setAllFillColor(dualMesh, RGB.WHITE);
   300→		PGS_Conversion.setAllStrokeColor(dualMesh, RGB.PINK, 2);
   301→		return dualMesh;
   302→	}
   303→
   304→	/**
   305→	 * Produces a quadrangulation from a triangulation, by splitting each triangle
   306→	 * into three quadrangles (using the <i>Catmull and Clark</i> technique). A
   307→	 * quadrangulation is a mesh where every face is a quadrangle.
   308→	 * <p>
   309→	 * Since this method employs a very simple technique to produce a
   310→	 * quadrangulation, the result is poor-quality, containing many helix-like
   311→	 * structures (it's not at all "regular").
   312→	 * <p>
   313→	 * Note that this method processes a Delaunay triangulation. Process a shape
   314→	 * using
   315→	 * {@link PGS_Triangulation#delaunayTriangulationMesh(PShape, Collection, boolean, int, boolean)
   316→	 * delaunayTriangulationMesh()} first and then feed it to this method.
   317→	 * 
   318→	 * @param triangulation a triangulation mesh
   319→	 * @return a GROUP PShape, where each child shape is one quadrangle
   320→	 * @since 1.2.0
   321→	 */
   322→	public static PShape splitQuadrangulation(final IIncrementalTin triangulation) {
   323→		// https://www.cs.mcgill.ca/~cs507/projects/1998/rachelp/welcome.html
   324→		final PShape quads = new PShape(PConstants.GROUP);
   325→
   326→		/*-
   327→		 * 1. Insert a Steiner point along the interior of every edge of each 
   328→		 * triangle.
   329→		 * 2. Insert an extra Steiner point in the interior of each triangle.
   330→		 * 3. Connect the Steiner point inside each triangle to the Steiner points on the
   331→		 * edges of that triangle.
   332→		 * Each triangle is converted into three quadrangles.
   333→		 */
   334→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   335→
   336→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   337→			final IConstraint constraint = t.getContainingRegion();
   338→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   339→				final PVector p1 = PGS_Triangulation.toPVector(t.getVertexA());
   340→				final PVector p2 = PGS_Triangulation.toPVector(t.getVertexB());
   341→				final PVector p3 = PGS_Triangulation.toPVector(t.getVertexC());
   342→				final PVector sA = PVector.add(p1, p2).div(2); // steiner point p1-p2
   343→				final PVector sB = PVector.add(p2, p3).div(2); // steiner point p2-p3
   344→				final PVector sC = PVector.add(p3, p1).div(2); // steiner point p3-p1
   345→
   346→				// compute ?barycenter? of triangle = interior steiner point
   347→				final PVector cSeg = PVector.add(sA, sB).div(2);
   348→				final PVector sI = PVector.add(cSeg, sC).div(2); // interior steiner point
   349→
   350→				// anti-clockwise, starting at original vertex
   351→				quads.addChild(PGS_Conversion.fromPVector(p1, sC, sI, sA, p1));
   352→				quads.addChild(PGS_Conversion.fromPVector(p2, sA, sI, sB, p2));
   353→				quads.addChild(PGS_Conversion.fromPVector(p3, sB, sI, sC, p3));
   354→			}
   355→		});
   356→
   357→		/*-
   358→		 * Now ideally "regularize" the mesh using techniques explored here:
   359→		 * https://acdl.mit.edu/ESP/Publications/AIAApaper2019-1988.pdf
   360→		 * https://acdl.mit.edu/ESP/Publications/IMR28.pdf
   361→		 */
   362→
   363→		PGS_Conversion.setAllFillColor(quads, RGB.WHITE);
   364→		PGS_Conversion.setAllStrokeColor(quads, RGB.PINK, 2);
   365→
   366→		return quads;
   367→	}
   368→
   369→	/**
   370→	 * Generates a quadrangulation from a triangulation by selectively removing (or
   371→	 * "collapsing") the edges shared by neighboring triangles (via edge coloring).
   372→	 * <p>
   373→	 * This method may be slow on large inputs (as measured by vertex count), owing
   374→	 * to the graph coloring it performs.
   375→	 * 
   376→	 * @param triangulation     a triangulation mesh
   377→	 * @param preservePerimeter whether to preserve the perimeter of the input
   378→	 *                          triangulation; when true, retains edges that lie on
   379→	 *                          the perimeter of the triangulation mesh that would
   380→	 *                          have otherwise been removed (this results in some
   381→	 *                          triangles being included in the output).
   382→	 * @return a GROUP PShape, where each child shape is one quadrangle
   383→	 * @since 1.2.0
   384→	 */
   385→	public static PShape edgeCollapseQuadrangulation(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   386→		/*-
   387→		 * From 'Fast unstructured quadrilateral mesh generation'.
   388→		 * A better coloring approach is given in 'Face coloring in unstructured CFD codes'.
   389→		 * 
   390→		 * First partition the edges of the triangular mesh into three groups such that
   391→		 * no triangle has two edges of the same color (find groups by reducing to a
   392→		 * graph-coloring).
   393→		 * Then obtain an all-quadrilateral mesh by removing all edges of *one* 
   394→		 * particular color.
   395→		 */
   396→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   397→		final AbstractBaseGraph<IQuadEdge, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
   398→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   399→			final IConstraint constraint = t.getContainingRegion();
   400→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   401→				graph.addVertex(t.getEdgeA().getBaseReference());
   402→				graph.addVertex(t.getEdgeB().getBaseReference());
   403→				graph.addVertex(t.getEdgeC().getBaseReference());
   404→
   405→				graph.addEdge(t.getEdgeA().getBaseReference(), t.getEdgeB().getBaseReference());
   406→				graph.addEdge(t.getEdgeA().getBaseReference(), t.getEdgeC().getBaseReference());
   407→				graph.addEdge(t.getEdgeB().getBaseReference(), t.getEdgeC().getBaseReference());
   408→			}
   409→		});
   410→
   411→		Coloring<IQuadEdge> coloring = new RLFColoring<>(graph).getColoring();
   412→
   413→		final HashSet<IQuadEdge> perimeter = new HashSet<>(triangulation.getPerimeter());
   414→		if (!unconstrained) {
   415→			perimeter.clear(); // clear, the perimeter of constrained tin is unaffected by the constraint
   416→		}
   417→
   418→		final Collection<PEdge> meshEdges = new ArrayList<>();
   419→		coloring.getColors().forEach((edge, color) -> {
   420→			/*
   421→			 * "We can remove the edges of any one of the colors, however a convenient
   422→			 * choice is the one that leaves the fewest number of unmerged boundary
   423→			 * triangles". -- ideal, but not implemented here...
   424→			 */
   425→			// NOTE could now apply Topological optimization, as given in paper.
   426→			if ((color < 2) || (preservePerimeter && (edge.isConstrainedRegionBorder() || perimeter.contains(edge)))) {
   427→				meshEdges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y));
   428→			}
   429→		});
   430→
   431→		PShape quads = PGS.polygonizeEdges(meshEdges);
   432→		if (triangulation.getConstraints().size() < 2) { // assume constraint 1 is the boundary (not a hole)
   433→			return quads;
   434→		} else {
   435→			return removeHoles(quads, triangulation);
   436→		}
   437→	}
   438→
   439→	/**
   440→	 * Generates a quadrangulation from a triangulation by "inverting" triangles
   441→	 * (for each triangle, create edges joining its centroid to each of its
   442→	 * vertices).
   443→	 * <p>
   444→	 * This approach tends to create a denser quad mesh than
   445→	 * {@link #edgeCollapseQuadrangulation(IIncrementalTin, boolean)
   446→	 * <code>edgeCollapseQuadrangulation()</code>} on the same input.
   447→	 * 
   448→	 * @param triangulation     a triangulation mesh
   449→	 * @param preservePerimeter whether to preserve the perimeter of the input
   450→	 *                          triangulation; when true, retains edges that lie on
   451→	 *                          the perimeter of the triangulation mesh that would
   452→	 *                          have otherwise been removed (this results in some
   453→	 *                          triangles being included in the output).
   454→	 * @return a GROUP PShape, where each child shape is one quadrangle
   455→	 * @since 1.2.0
   456→	 */
   457→	public static PShape centroidQuadrangulation(final IIncrementalTin triangulation, final boolean preservePerimeter) {
   458→		final boolean unconstrained = triangulation.getConstraints().isEmpty();
   459→		final HashSet<PEdge> edges = new HashSet<>();
   460→		TriangleCollector.visitSimpleTriangles(triangulation, t -> {
   461→			final IConstraint constraint = t.getContainingRegion();
   462→			if (unconstrained || (constraint != null && constraint.definesConstrainedRegion())) {
   463→				Vertex centroid = centroid(t);
   464→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexA().x, t.getVertexA().y));
   465→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexB().x, t.getVertexB().y));
   466→				edges.add(new PEdge(centroid.getX(), centroid.getY(), t.getVertexC().x, t.getVertexC().y));
   467→			}
   468→		});
   469→
   470→		if (preservePerimeter) {
   471→			List<IQuadEdge> perimeter = triangulation.getPerimeter();
   472→			triangulation.edges().forEach(edge -> {
   473→				if (edge.isConstrainedRegionBorder() || (unconstrained && perimeter.contains(edge))) {
   474→					edges.add(new PEdge(edge.getA().x, edge.getA().y, edge.getB().x, edge.getB().y));
   475→				}
   476→			});
   477→		}
   478→
   479→		final PShape quads = PGS.polygonizeEdges(edges);
   480→		if (triangulation.getConstraints().size() < 2) { // assume constraint 1 is the boundary (not a hole)
   481→			return quads;
   482→		} else {
   483→			return removeHoles(quads, triangulation);
   484→		}
   485→	}
   486→
   487→	/**
   488→	 * Removes (what should be) holes from a polygonized quadrangulation.
   489→	 * <p>
   490→	 * When the polygonizer is applied to the collapsed triangles of a
   491→	 * triangulation, it cannot determine which collapsed regions represent holes in
   492→	 * the quadrangulation and will consequently fill them in. The subroutine below
   493→	 * restores holes/topology, detecting which polygonized face(s) are original
   494→	 * holes. Note the geometry of the original hole/constraint and its associated
   495→	 * polygonized face are different, since quads are polygonized, not triangles
   496→	 * (hence an overlap metric is used to match candidates).
   497→	 * 
   498→	 * @param faces         faces of the quadrangulation
   499→	 * @param triangulation
   500→	 * @return
   501→	 */
   502→	private static PShape removeHoles(PShape faces, IIncrementalTin triangulation) {
   503→		List<IConstraint> holes = new ArrayList<>(triangulation.getConstraints()); // copy list
   504→		holes = holes.subList(1, holes.size()); // slice off perimeter constraint (not a hole)
   505→
   506→		STRtree tree = new STRtree();
   507→		holes.stream().map(constraint -> constraint.getVertices()).iterator().forEachRemaining(vertices -> {
   508→			CoordinateList coords = new CoordinateList(); // coords of constraint
   509→			vertices.forEach(v -> coords.add(new Coordinate(v.x, v.y)));
   510→			coords.closeRing();
   511→
   512→			if (!Orientation.isCCWArea(coords.toCoordinateArray())) { // triangulation holes are CW
   513→				Polygon polygon = PGS.GEOM_FACTORY.createPolygon(coords.toCoordinateArray());
   514→				tree.insert(polygon.getEnvelopeInternal(), polygon);
   515→			}
   516→		});
   517→
   518→		List<PShape> nonHoles = PGS_Conversion.getChildren(faces).parallelStream().filter(quad -> {
   519→			/*
   520→			 * If quad overlaps with a hole detect whether it *is* that hole via Hausdorff
   521→			 * Similarity.
   522→			 */
   523→			final Geometry g = PGS_Conversion.fromPShape(quad);
   524→
   525→			@SuppressWarnings("unchecked")
   526→			List<Polygon> matches = tree.query(g.getEnvelopeInternal());
   527→
   528→			for (Polygon m : matches) {
   529→				try {
   530→					// PGS_ShapePredicates.overlap() inlined here
   531→					Geometry overlap = OverlayNG.overlay(m, g, OverlayNG.INTERSECTION);
   532→					double a1 = g.getArea();
   533→					double a2 = m.getArea();
   534→					double total = a1 + a2;
   535→					double aOverlap = overlap.getArea();
   536→					double w1 = a1 / total;
   537→					double w2 = a2 / total;
   538→
   539→					double similarity = w1 * (aOverlap / a1) + w2 * (aOverlap / a2);
   540→					if (similarity > 0.2) { // magic constant, unsure what the best value is
   541→						return false; // is hole; keep=false
   542→					}
   543→				} catch (Exception e) { // catch occasional noded error
   544→					continue;
   545→				}
   546→
   547→			}
   548→			return true; // is not hole; keep=true
   549→		}).collect(Collectors.toList());
   550→
   551→		return PGS_Conversion.flatten(nonHoles);
   552→	}
   553→
   554→	/**
   555→	 * Produces a quadrangulation from a point set. The resulting quadrangulation
   556→	 * has a characteristic spiral pattern.
   557→	 * 
   558→	 * @param points
   559→	 * @return a GROUP PShape where each child shape is a single face
   560→	 * @since 1.2.0
   561→	 */
   562→	public static PShape spiralQuadrangulation(List<PVector> points) {
   563→		SpiralQuadrangulation sq = new SpiralQuadrangulation(points);
   564→		return PGS.polygonizeEdges(sq.getQuadrangulationEdges());
   565→	}
   566→
   567→	/**
   568→	 * Transforms a non-conforming mesh shape into a <i>conforming mesh</i> by
   569→	 * performing a "noding" operation. "noding" refers to the process of splitting
   570→	 * edges into two at points where they intersect or touch another edge. It is a
   571→	 * way of ensuring consistency and accuracy in the spatial topology of the mesh.
   572→	 * 
   573→	 * @param shape a GROUP PShape which represents a mesh-like shape, but one that
   574→	 *              isn't conforming (i.e. adjacent edges do not necessarily have
   575→	 *              identical start and end coordinates)
   576→	 * @return the input shape, having been noded and polygonized
   577→	 * @since <code>public</code> since 1.3.1
   578→	 */
   579→	public static PShape nodeNonMesh(PShape shape) {
   580→		final List<SegmentString> segmentStrings = new ArrayList<>(shape.getChildCount() * 3);
   581→
   582→		for (PShape face : shape.getChildren()) {
   583→			for (int i = 0; i < face.getVertexCount(); i++) {
   584→				final PVector a = face.getVertex(i);
   585→				final PVector b = face.getVertex((i + 1) % face.getVertexCount());
   586→				if (!a.equals(b)) {
   587→					segmentStrings.add(PGS.createSegmentString(a, b));
   588→				}
   589→			}
   590→		}
   591→		return PGS.polygonizeSegments(segmentStrings, true);
   592→	}
   593→
   594→	/**
   595→	 * Randomly merges together / dissolves adjacent faces of a mesh.
   596→	 * <p>
   597→	 * The procedure randomly assigns a integer ID to each face and then groups of
   598→	 * mutually adjacent faces that share an ID (belong to the same group) are
   599→	 * merged into one.
   600→	 * 
   601→	 * @param mesh     the conforming mesh shape to perform the operation on
   602→	 * @param nClasses the number of classes to assign to mesh faces; fewer classes
   603→	 *                 means adjacent faces are more likely to share a class and be
   604→	 *                 merged.
   605→	 * @param seed     the seed for the random number generator
   606→	 * @return a new GROUP PShape representing the result of the operation
   607→	 * @since 1.3.1
   608→	 */
   609→	public static PShape stochasticMerge(PShape mesh, int nClasses, long seed) {
   610→		final RandomGenerator random = new XoRoShiRo128PlusRandomGenerator(seed);
   611→		SimpleGraph<PShape, DefaultEdge> graph = PGS_Conversion.toDualGraph(mesh);
   612→		Map<PShape, Integer> classes = new HashMap<>();
   613→		graph.vertexSet().forEach(v -> classes.put(v, random.nextInt(Math.max(nClasses, 1))));
   614→
   615→		/*
   616→		 * Handle "island" faces, which are faces whose neighbours all have the same
   617→		 * class (which differ from the island itself).
   618→		 */
   619→		NeighborCache<PShape, DefaultEdge> cache = new NeighborCache<>(graph);
   620→		graph.vertexSet().forEach(v -> {
   621→			final int vClass = classes.get(v);
   622→			List<PShape> neighbours = cache.neighborListOf(v);
   623→			final int nClass1 = classes.get(neighbours.get(0));
   624→			if (vClass == nClass1) {
   625→				return; // certainly not an island
   626→			}
   627→
   628→			neighbours.removeIf(n -> classes.get(n) == nClass1);
   629→			if (neighbours.isEmpty()) {
   630→				classes.put(v, nClass1); // reassign face class
   631→			}
   632→		});
   633→
   634→		List<DefaultEdge> toRemove = new ArrayList<>();
   635→		graph.edgeSet().forEach(e -> {
   636→			PShape a = graph.getEdgeSource(e);
   637→			PShape b = graph.getEdgeTarget(e);
   638→			if (!classes.get(a).equals(classes.get(b))) {
   639→				toRemove.add(e);
   640→			}
   641→		});
   642→		graph.removeAllEdges(toRemove);
   643→		ConnectivityInspector<PShape, DefaultEdge> ci = new ConnectivityInspector<>(graph);
   644→
   645→		List<PShape> blobs = ci.connectedSets().stream().map(group -> PGS_ShapeBoolean.unionMesh(PGS_Conversion.flatten(group)))
   646→				.collect(Collectors.toList());
   647→		return PGS_Conversion.flatten(blobs);
   648→	}
   649→
   650→	/**
   651→	 * Smoothes a mesh via iterative weighted <i>Laplacian smoothing</i>. The effect
   652→	 * of which is mesh faces become more uniform in size and shape (isotropic).
   653→	 * <p>
   654→	 * In Laplacian smoothing, vertices are replaced with the (weighted) average of
   655→	 * the positions of their adjacent vertices; it is computationally inexpensive
   656→	 * and fairly effective (faces become more isotropic), but it does not guarantee
   657→	 * improvement in element quality.
   658→	 * <p>
   659→	 * Meshes with more faces take more iterations to converge to stable point.
   660→	 * Meshes with highly convex faces may result in issues.
   661→	 * 
   662→	 * @param mesh              a GROUP PShape where each child shape is a single
   663→	 *                          face comprising a conforming mesh
   664→	 * @param iterations        number of smoothing passes to perform. Most meshes
   665→	 *                          will converge very well by around 50-100 passes.
   666→	 * @param preservePerimeter boolean flag to exclude the boundary vertices from
   667→	 *                          being smoothed (thus preserving the mesh perimeter).
   668→	 *                          Generally this should be set to true, otherwise the
   669→	 *                          mesh will shrink as it is smoothed.
   670→	 * @return the smoothed mesh
   671→	 * @since 1.3.1
   672→	 */
   673→	public static PShape smoothMesh(PShape mesh, int iterations, boolean preservePerimeter) {
   674→		PMesh m = new PMesh(mesh);
   675→		for (int i = 0; i < iterations; i++) {
   676→			m.smoothWeighted(preservePerimeter);
   677→		}
   678→		return m.getMesh();
   679→	}
   680→
   681→	/**
   682→	 * Smoothes a mesh via iterative weighted <i>Laplacian smoothing</i>. The effect
   683→	 * of which is mesh faces become more uniform in size and shape (isotropic).
   684→	 * <p>
   685→	 * This particular method iteratively smoothes the mesh until the displacement
   686→	 * of the most displaced vertex in the prior iteration is less than
   687→	 * <code>displacementCutoff</code>.
   688→	 * <p>
   689→	 * In Laplacian smoothing, vertices are replaced with the (weighted) average of
   690→	 * the positions of their adjacent vertices; it is computationally inexpensive
   691→	 * and fairly effective (faces become more isotropic), but it does not guarantee
   692→	 * improvement in element quality.
   693→	 * <p>
   694→	 * Meshes with more faces take more iterations to converge to stable point.
   695→	 * Meshes with highly convex faces may result in issues.
   696→	 * 
   697→	 * @param mesh               a GROUP PShape where each child shape is a single
   698→	 *                           face comprising a conforming mesh
   699→	 * @param displacementCutoff the
   700→	 * @param preservePerimeter  boolean flag to exclude the boundary vertices from
   701→	 *                           being smoothed (thus preserving the mesh
   702→	 *                           perimeter). Generally this should be set to true,
   703→	 *                           otherwise the mesh will shrink as it is smoothed.
   704→	 * @return the smoothed mesh
   705→	 * @since 1.3.1
   706→	 */
   707→	public static PShape smoothMesh(PShape mesh, double displacementCutoff, boolean preservePerimeter) {
   708→		displacementCutoff = Math.max(displacementCutoff, 1e-3);
   709→		PMesh m = new PMesh(mesh);
   710→
   711→		double displacement;
   712→		do {
   713→			displacement = m.smoothWeighted(preservePerimeter);
   714→		} while (displacement > displacementCutoff);
   715→		return m.getMesh();
   716→	}
   717→
   718→	/**
   719→	 * Simplifies the boundaries of the faces in a mesh while preserving the
   720→	 * original mesh topology.
   721→	 * 
   722→	 * @param mesh              GROUP shape comprising the faces of a conforming
   723→	 *                          mesh
   724→	 * @param tolerance         the simplification tolerance for area-based
   725→	 *                          simplification. Roughly equal to the maximum
   726→	 *                          distance by which a simplified line can change from
   727→	 *                          the original.
   728→	 * @param preservePerimeter whether to only simplify inner-boundaries and
   729→	 *                          leaving outer boundary edges unchanged.
   730→	 * @return GROUP shape comprising the simplfied mesh faces
   731→	 * @since 1.3.1
   732→	 */
   733→	public static PShape simplifyMesh(PShape mesh, double tolerance, boolean preservePerimeter) {
   734→		Geometry[] geometries = PGS_Conversion.getChildren(mesh).stream().map(s -> PGS_Conversion.fromPShape(s)).toArray(Geometry[]::new);
   735→		CoverageSimplifier simplifier = new CoverageSimplifier(geometries);
   736→		Geometry[] output;
   737→		if (preservePerimeter) {
   738→			output = simplifier.simplifyInner(tolerance);
   739→		} else {
   740→			output = simplifier.simplify(tolerance);
   741→		}
   742→		return PGS_Conversion.toPShape(Arrays.asList(output));
   743→	}
   744→
   745→	/**
   746→	 * Recursively merges smaller faces of a mesh into their adjacent faces. The
   747→	 * procedure continues until there are no resulting faces with an area smaller
   748→	 * than the specified threshold.
   749→	 * 
   750→	 * @param mesh          a GROUP shape representing a conforming mesh the mesh to
   751→	 *                      perform area merging on
   752→	 * @param areaThreshold The maximum permissible area threshold for merging
   753→	 *                      faces. Any faces smaller than this threshold will be
   754→	 *                      consolidated into their neighboring faces.
   755→	 * @return GROUP shape comprising the merged mesh faces
   756→	 * @since 1.3.1
   757→	 */
   758→	public static PShape areaMerge(PShape mesh, double areaThreshold) {
   759→		PShape merged = AreaMerge.areaMerge(mesh, areaThreshold);
   760→		return merged;
   761→	}
   762→
   763→	/**
   764→	 * Splits each edge of a given mesh shape into a specified number of
   765→	 * equal-length parts and creates a new shape from the resulting smaller edges.
   766→	 * This method preserves the overall topology of the original mesh.
   767→	 * 
   768→	 * @param split The PShape representing a polygon to be split into smaller
   769→	 *              edges.
   770→	 * @param parts The number of equal parts each edge of the polygon should be
   771→	 *              split into. Should be a positive integer, but if less than 1,
   772→	 *              it's reset to 1.
   773→	 * @return A new mesh PShape created from the split edges.
   774→	 * @since 1.3.1
   775→	 */
   776→	public static PShape splitEdges(PShape split, int parts) {
   777→		parts = Math.max(1, parts);
   778→		HashSet<PEdge> edges = new HashSet<>(PGS_SegmentSet.fromPShape(split));
   779→		List<PEdge> splitEdges = new ArrayList<>(edges.size() * parts);
   780→
   781→		for (PEdge edge : edges) {
   782→			double from = 0;
   783→			double step = 1.0 / parts;
   784→			for (int i = 0; i < parts; i++) {
   785→				double to = from + step;
   786→				PEdge subEdge = edge.slice(from, to);
   787→				splitEdges.add(subEdge);
   788→				from = to;
   789→			}
   790→		}
   791→
   792→		return PGS.polygonizeEdges(splitEdges);
   793→	}
   794→
   795→	/**
   796→	 * Calculate the longest edge of a given triangle.
   797→	 */
   798→	private static IQuadEdge findLongestEdge(final SimpleTriangle t) {
   799→		if (t.getEdgeA().getLength() > t.getEdgeB().getLength()) {
   800→			if (t.getEdgeC().getLength() > t.getEdgeA().getLength()) {
   801→				return t.getEdgeC();
   802→			} else {
   803→				return t.getEdgeA();
   804→			}
   805→		} else {
   806→			if (t.getEdgeC().getLength() > t.getEdgeB().getLength()) {
   807→				return t.getEdgeC();
   808→			} else {
   809→				return t.getEdgeB();
   810→			}
   811→		}
   812→	}
   813→
   814→	private static double[] midpoint(final IQuadEdge edge) {
   815→		final Vertex a = edge.getA();
   816→		final Vertex b = edge.getB();
   817→		return new double[] { (a.x + b.x) / 2d, (a.y + b.y) / 2d };
   818→	}
   819→
   820→	private static Vertex centroid(final SimpleTriangle t) {
   821→		final Vertex a = t.getVertexA();
   822→		final Vertex b = t.getVertexB();
   823→		final Vertex c = t.getVertexC();
   824→		double x = a.x + b.x + c.x;
   825→		x /= 3;
   826→		double y = a.y + b.y + c.y;
   827→		y /= 3;
   828→		return new Vertex(x, y, 0);
   829→	}
   830→
   831→}
   832→

