   322→	/**
   323→	 * Generates a hexagon grid/lattice of points that lie within a bounding
   324→	 * rectangle.
   325→	 * 
   326→	 * @param xMin x-coordinate of boundary minimum
   327→	 * @param yMin y-coordinate of boundary minimum
   328→	 * @param xMax x-coordinate of boundary maximum
   329→	 * @param yMax y-coordinate of boundary maximum
   330→	 * @param n    number of points to generate
   331→	 * @return
   332→	 * @see #hexGrid(double, double, double, double, double) hexGrid() where
   333→	 *      inter-point distance is specified
   334→	 */
   335→	public static List<PVector> hexGrid(final double xMin, final double yMin, final double xMax, final double yMax, final int n) {
   336→		final double width = xMax - xMin;
   337→		final double height = yMax - yMin;
   338→
   339→		final float h = (float) Math.sqrt((width * height * (Math.sqrt(5) / 2)) / n);
   340→		final float v = (float) (h * (2 / Math.sqrt(5)));
   341→		final List<PVector> points = new ArrayList<>(n);
   342→
   343→		for (int i = 0; i < width / h; i++) {
   344→			for (int j = 0; j < height / v; j++) {
   345→				points.add(new PVector((i - (j % 2) / 2f) * h + (float) xMin, j * v + (float) yMin));
   346→			}
   347→		}
   348→		return points;
   349→	}
