   351→	/**
   352→	 * Generates a hexagon grid of points that lie within a bounding rectangle.
   353→	 * 
   354→	 * @param xMin          x-coordinate of boundary minimum
   355→	 * @param yMin          y-coordinate of boundary minimum
   356→	 * @param xMax          x-coordinate of boundary maximum
   357→	 * @param yMax          y-coordinate of boundary maximum
   358→	 * @param pointDistance inter-point distance
   359→	 * @return
   360→	 * @see #hexGrid(double, double, double, double, int) hexGrid() where number of
   361→	 *      points is specified
   362→	 */
   363→	public static List<PVector> hexGrid(final double xMin, final double yMin, final double xMax, final double yMax,
   364→			final double pointDistance) {
   365→		final double width = xMax - xMin;
   366→		final double height = yMax - yMin;
   367→
   368→		final List<PVector> points = new ArrayList<>();
   369→
   370→		for (int i = 0; i < width / pointDistance; i++) {
   371→			for (int j = 0; j < height / pointDistance; j++) {
   372→				points.add(new PVector((float) ((i - (j % 2) / 2f) * pointDistance + xMin), (float) (j * pointDistance + yMin)));
   373→			}
   374→		}
   375→		return points;
   376→	}
   377→
   378→	/**
   379→	 * Generates a hexagonal grid of points <b>arranged in a hexagon pattern</b>.
   380→	 * 
   381→	 * @param centerX x coordinate of the hexagon center point
   382→	 * @param centerY y coordinate of the hexagon center point
   383→	 * @param length  layers/no. of points on each hexagon side
   384→	 * @distance inter-point distance
   385→	 * @return
   386→	 */
   387→	public static List<PVector> hexagon(double centerX, double centerY, int length, double distance) {
   388→		final float xOffset = (float) centerX;
   389→		final float yOffset = (float) centerY;
   390→		final float d = (float) distance;
   391→
   392→		final List<PVector> points = new ArrayList<>();
   393→
   394→		/*
   395→		 * PVector .z is set to length so hexagon layer can be easily identified.
   396→		 */
   397→		for (int i = 0; i <= (length - 1); i++) {
   398→			float y = (SQRT_3 * i * d) / 2.0f;
   399→			for (int j = 0; j < (2 * length - 1 - i); j++) {
   400→				float x = (-(2 * length - i - 2) * d) / 2.0f + j * d;
   401→				points.add(new PVector(x + xOffset, y + yOffset, length));
   402→				if (y != 0) {
   403→					points.add(new PVector(x + xOffset, -y + yOffset, length));
   404→				}
   405→			}
   406→		}
   407→		return points;
   408→	}
   409→
   410→	/**
   411→	 * Generates a set of n points that are randomly distributed on a ring
   412→	 * (annulus).
   413→	 * 
   414→	 * @param centerX     x coordinate of the center/mean of the ring
   415→	 * @param centerY     x coordinate of the center/mean of the ring
   416→	 * @param innerRadius radius of the ring's hole
   417→	 * @param outerRadius outer radius of the ring
   418→	 * @param maxAngle    angle of the ring (in radians). Can be negative
   419→	 * @param n           the number of random points to generate
   420→	 * @return a list of PVector objects representing the (x, y) coordinates of the
   421→	 *         random points
