   582→	/**
   583→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   584→	 * from a low discrepancy sequence (LDS) based on an irrational number (the
   585→	 * plastic constant).
   586→	 * <p>
   587→	 * The <i>plastic LDS</i> has been <a href=
   588→	 * "http://extremelearning.com.au/unreasonable-effectiveness-of-quasirandom-sequences/">shown</a>
   589→	 * to have superior low discrepancy properties amongst the quasirandom
   590→	 * sequences, and is therefore recommended.
   591→	 * <p>
   592→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   593→	 * that are low discrepancy - meaning the points tend not to clump together and
   594→	 * leave holes; the resulting point set is more evenly spaced than a simple
   595→	 * random distribution but less regular than lattices.
   596→	 * 
   597→	 * @param xMin x-coordinate of boundary minimum
   598→	 * @param yMin y-coordinate of boundary minimum
   599→	 * @param xMax x-coordinate of boundary maximum
   600→	 * @param yMax y-coordinate of boundary maximum
   601→	 * @param n    number of points to generate
   602→	 * @return
   603→	 */
   604→	public static List<PVector> plasticLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   605→		// https://github.com/Atrix256/SampleZoo/blob/master/src/families/_2d/samples/irrational_numbers/irrational_numbers.cpp
   606→		final double w = xMax - xMin;
   607→		final double h = yMax - yMin;
   608→		final double p = 1.32471795724474602596; // plastic constant
   609→		final double a1 = 1.0 / p; // inverse of plastic number
   610→		final double a2 = 1.0 / (p * p);
   611→
   612→		final List<PVector> points = new ArrayList<>(n);
   613→		for (int i = 0; i < n; i++) {
   614→			final float x = (float) (((0.5 + a1 * i) % 1) * w + xMin);
   615→			final float y = (float) (((0.5 + a2 * i) % 1) * h + yMin);
   616→			points.add(new PVector(x, y));
   617→		}
   618→		return points;
   619→	}
