   119→	 *                    spaced and sized. 0...3 is a suitable range for this
   120→	 *                    parameter
   121→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   122→	 *         the center point and .z represents radius.
   123→	 */
   124→	public static List<PVector> trinscribedPack(PShape shape, int points, int refinements) {
   125→		final List<PVector> steinerPoints = PGS_Processing.generateRandomPoints(shape, points);
   126→		final IIncrementalTin tin = PGS_Triangulation.delaunayTriangulationMesh(shape, steinerPoints, true, refinements, true);
   127→		return StreamSupport.stream(tin.triangles().spliterator(), false).filter(filterBorderTriangles).map(t -> inCircle(t))
   128→				.collect(Collectors.toList());
