   164→	/**
   165→	 * 
   166→	 * Generates a seeded random circle packing within the input shape. Circles are
   167→	 * created one-by-one by generating random points and calculating the maximum
   168→	 * possible radius for a circle at each point, ensuring it is tangent to its
   169→	 * nearest circle or shape vertex.
   170→	 * <p>
   171→	 * The {@code points} parameter defines the number of random point attempts (or
   172→	 * circle attempts), but not the exact number of circles in the final packing
   173→	 * output. An attempted point is rejected if it lies within an existing circle
   174→	 * or if its nearest circle is less than {@code minRadius} distance away.
   175→	 * <p>
   176→	 * Thus, {@code points} defines the maximum number of circles the packing can
   177→	 * have; in practice, the packing will contain somewhat fewer circles.
   178→	 * <p>
   179→	 * The generated circles in the packing do not overlap and are contained
   180→	 * entirely within the shape. However, not every circle is necessarily tangent
   181→	 * to other circles; such circles will be tangent to a shape vertex.
   182→	 * 
   183→	 * @param shape             the shape within which to generate the circle
   184→	 *                          packing
   185→	 * @param points            number of random points to generate (not necessarily
   186→	 *                          equal to the number of circles in the packing)
   187→	 * @param minRadius         minimum allowed radius for circles in the packing
   188→	 *                          (affects packing generation, not applied as a filter
   189→	 *                          at the end)
   190→	 * @param triangulatePoints when true, triangulates the initial random point set
   191→	 *                          and uses triangle centroids as the random point set
   192→	 *                          instead; results in a more evenly distributed
   193→	 *                          packing (particularly when the number of points is
   194→	 *                          small), which may be desirable
   195→	 * @param seed              random seed used to initialize the underlying random
   196→	 *                          number generator
   197→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   198→	 *         the center point, and .z represents the radius.
   199→	 */
   200→	public static List<PVector> stochasticPack(final PShape shape, final int points, final double minRadius, boolean triangulatePoints,
   201→			long seed) {
   202→
   203→		final CoverTree<PVector> tree = CoverTree.create(3, 2, circleDistanceMetric);
   204→		final List<PVector> out = new ArrayList<>();
   205→
   206→		List<PVector> steinerPoints = PGS_Processing.generateRandomPoints(shape, points, seed);
   207→		if (triangulatePoints) {
   208→			final IIncrementalTin tin = PGS_Triangulation.delaunayTriangulationMesh(shape, steinerPoints, true, 1, true);
   209→			steinerPoints = StreamSupport.stream(tin.triangles().spliterator(), false).filter(filterBorderTriangles)
   210→					.map(PGS_CirclePacking::centroid).collect(Collectors.toList());
   211→		}
   212→
   213→		// Model shape vertices as circles of radius 0, to constrain packed circles
   214→		// within shape edge
   215→		final List<PVector> vertices = PGS_Conversion.toPVector(shape);
   216→		Collections.shuffle(vertices); // shuffle vertices to reduce tree imbalance during insertion
   217→		vertices.forEach(p -> tree.insert(new double[] { p.x, p.y, 0 }, p));
   218→
   219→		/*
   220→		 * "To find the circle nearest to a center (x, y), do a proximity search at (x,
   221→		 * y, R), where R is greater than or equal to the maximum radius of a circle."
   222→		 */
   223→		float largestR = 0; // the radius of the largest circle in the tree
   224→
   225→		for (PVector p : steinerPoints) {
   226→			final PointEntryDist<PVector> nn = tree.query1NN(new double[] { p.x, p.y, largestR }); // find nearest-neighbour circle
   227→
   228→			/*
   229→			 * nn.dist() does not return the radius (since it's a distance metric used to
   230→			 * find nearest circle), so calculate maximum radius for candidate circle using
   231→			 * 2d euclidean distance between center points minus radius of nearest circle.
   232→			 */
   233→			final float dx = p.x - nn.value().x;
   234→			final float dy = p.y - nn.value().y;
   235→			final float radius = (float) (Math.sqrt(dx * dx + dy * dy) - nn.value().z);
   236→			if (radius > minRadius) {
   237→				largestR = (radius >= largestR) ? radius : largestR;
   238→				p.z = radius;
   239→				tree.insert(new double[] { p.x, p.y, radius }, p); // insert circle into tree
   240→				out.add(p);
   241→			}
   242→		}
   243→		return out;
   244→	}
