   246→	/**
   247→	 * Generates a random circle packing of tangential circles with varying radii
   248→	 * that overlap the given shape. The method name references the packing
   249→	 * algorithm used (Front Chain Packing), rather than any particular
   250→	 * characteristic of the circle packing.
   251→	 * <p>
   252→	 * You can set <code>radiusMin</code> equal to <code>radiusMax</code> for a
   253→	 * packing of equal-sized circles using this approach.
   254→	 *
   255→	 * @param shape     the shape within which to generate the circle packing
   256→	 * @param radiusMin minimum radius of circles in the packing
   257→	 * @param radiusMax maximum radius of circles in the packing
   258→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   259→	 *         the center point and .z represents radius.
   260→	 */
   261→	public static List<PVector> frontChainPack(PShape shape, double radiusMin, double radiusMax) {
   262→		radiusMin = Math.max(1f, Math.min(radiusMin, radiusMax)); // choose min and constrain
   263→		radiusMax = Math.max(1f, Math.max(radiusMin, radiusMax)); // choose max and constrain
   264→		final Geometry g = fromPShape(shape);
   265→		final Envelope e = g.getEnvelopeInternal();
   266→		IndexedPointInAreaLocator pointLocator;
   267→
   268→		final FrontChainPacker packer = new FrontChainPacker((float) e.getWidth(), (float) e.getHeight(), (float) radiusMin,
   269→				(float) radiusMax, (float) e.getMinX(), (float) e.getMinY());
   270→
   271→		if (radiusMin == radiusMax) {
   272→			// if every circle same radius, use faster contains check
   273→			pointLocator = new IndexedPointInAreaLocator(g.buffer(radiusMax));
   274→			packer.getCircles().removeIf(p -> pointLocator.locate(PGS.coordFromPVector(p)) == Location.EXTERIOR);
   275→		} else {
   276→			pointLocator = new IndexedPointInAreaLocator(g);
   277→			final PreparedGeometry cache = PreparedGeometryFactory.prepare(g);
   278→			final GeometricShapeFactory circleFactory = new GeometricShapeFactory();
   279→			circleFactory.setNumPoints(8); // approximate circles using octagon for intersects check
   280→			packer.getCircles().removeIf(p -> {
   281→				// first test whether shape contains circle center point (somewhat faster)
   282→				if (pointLocator.locate(PGS.coordFromPVector(p)) != Location.EXTERIOR) {
   283→					return false;
   284→				}
   285→
   286→				// if center point not in circle, check whether circle overlaps with shape using
   287→				// intersects() (somewhat slower)
   288→				circleFactory.setCentre(PGS.coordFromPVector(p));
   289→				circleFactory.setSize(p.z * 2); // set diameter
   290→				return !cache.intersects(circleFactory.createCircle());
   291→			});
   292→		}
   293→
   294→		return packer.getCircles();
   295→	}
