   297→	/**
   298→	 * Packs a specified number of maximum inscribed circles within the given shape
   299→	 * using the Largest Empty Circle (LEC) algorithm.
   300→	 * <p>
   301→	 * This method finds and returns the maximum inscribed circles up to the
   302→	 * specified number (n), starting with the largest circle. It uses a tolerance
   303→	 * value to control the accuracy of the LEC algorithm.
   304→	 *
   305→	 * @param shape     The input shape to pack maximum inscribed circles within.
   306→	 * @param n         The number of maximum inscribed circles to find and pack.
   307→	 * @param tolerance The tolerance value to control the LEC algorithm's accuracy.
   308→	 *                  Higher values yield faster results but lower accuracy. A
   309→	 *                  value of a 1 is good staring point.
   310→	 * @return A list of PVector objects representing the centers (.x, .y) and radii
   311→	 *         (.z) of the maximum inscribed circles.
   312→	 */
   313→	public static List<PVector> maximumInscribedPack(PShape shape, int n, double tolerance) {
   314→		tolerance = Math.max(0.01, tolerance);
   315→		LargestEmptyCircles mics = new LargestEmptyCircles(fromPShape(shape), null, tolerance);
   316→
   317→		final List<PVector> out = new ArrayList<>();
   318→		for (int i = 0; i < n; i++) {
   319→			double[] c = mics.findNextLEC();
   320→			out.add(new PVector((float) c[0], (float) c[1], (float) c[2]));
   321→		}
   322→
   323→		return out;
   324→	}
