   326→	/**
   327→	 * Packs maximum inscribed circles within the given shape using the Largest
   328→	 * Empty Circle (LEC) algorithm.
   329→	 * <p>
   330→	 * This method finds and returns the maximum inscribed circles with a radius
   331→	 * equal to or larger than the specified minimum radius. It uses a tolerance
   332→	 * value to control the accuracy of the LEC algorithm.
   333→	 *
   334→	 * @param shape     The input shape to pack maximum inscribed circles within.
   335→	 * @param minRadius The minimum allowed radius for the inscribed circles.
   336→	 * @param tolerance The tolerance value to control the LEC algorithm's accuracy.
   337→	 *                  Higher values yield faster results but lower accuracy. A
   338→	 *                  value of a 1 is good staring point.
   339→	 * @return A list of PVector objects representing the centers (.x, .y) and radii
   340→	 *         (.z) of the maximum inscribed circles.
   341→	 */
   342→	public static List<PVector> maximumInscribedPack(PShape shape, double minRadius, double tolerance) {
   343→		tolerance = Math.max(0.01, tolerance);
   344→		minRadius = Math.max(0.01, minRadius);
   345→		LargestEmptyCircles mics = new LargestEmptyCircles(fromPShape(shape), null, tolerance);
   346→
   347→		final List<PVector> out = new ArrayList<>();
   348→		double[] currentLEC;
   349→		do {
   350→			currentLEC = mics.findNextLEC();
   351→			if (currentLEC[2] >= minRadius) {
   352→				out.add(new PVector((float) currentLEC[0], (float) currentLEC[1], (float) currentLEC[2]));
   353→			}
   354→		} while (currentLEC[2] >= minRadius);
   355→
   356→		return out;
   357→	}
