   405→	/**
   406→	 * Generates a random circle packing of circles with varying radii that overlap
   407→	 * the given shape.
   408→	 * <p>
   409→	 * Repulsion-packing involves iterative pair-repulsion, in which overlapping
   410→	 * circles move away from each other until there is no overlap. A packing is
   411→	 * first computed for the envelope of the shape, and then any circles which do
   412→	 * not overlap with the shape are discarded.
   413→	 * 
   414→	 * @param shape     the shape from which to generate a circle packing
   415→	 * @param radiusMin minimum radius of circles in the packing. the radii
   416→	 *                  parameters can be the same.
   417→	 * @param radiusMax maximum radius of circles in the packing. the radii
   418→	 *                  parameters can be the same.
   419→	 * @param seed      for initial circle positions and radii
   420→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   421→	 *         the center point and .z represents radius.
   422→	 * @since 1.3.0
   423→	 * @see #repulsionPack(PShape, List)
   424→	 */
   425→	public static List<PVector> repulsionPack(PShape shape, double radiusMin, double radiusMax, long seed) {
   426→		final double rMinA = Math.max(1f, Math.min(radiusMin, radiusMax)); // actual min
   427→		final double rMaxA = Math.max(1f, Math.max(radiusMin, radiusMax)); // actual max
   428→		final Geometry g = fromPShape(shape);
   429→		final Envelope e = g.getEnvelopeInternal();
   430→
   431→		/*
   432→		 * We want spawn N circles, such that there are enough to (theoretically) cover
   433→		 * the envelope exactly without any overlap, assuming a packing efficiency of
   434→		 * ~85% (close to optimum).
   435→		 */
   436→		double totalArea = e.getArea() * 0.85;
   437→		/*
   438→		 * Average area is not a simple mean since circle area is quadratic with regards
   439→		 * to radius. The actual average area of circles with radii a...b is an integral
   440→		 * of: pi*r^2 dr from r=a to b.
   441→		 */
   442→		double avgCircleArea = ((rMaxA * rMaxA * rMaxA) - (rMinA * rMinA * rMinA));
   443→		avgCircleArea *= (Math.PI / (3 * (rMaxA - rMinA)));
   444→		int n = (int) (totalArea / avgCircleArea);
   445→
   446→		List<PVector> points = PGS_PointSet.poissonN(e.getMinX() + rMaxA, e.getMinY() + rMaxA, e.getMaxX() - rMaxA, e.getMaxY() - rMaxA, n,
   447→				seed);
   448→		SplittableRandom r = new SplittableRandom(seed);
   449→		points.forEach(p -> p.z = rMaxA == rMinA ? (float) rMaxA : (float) r.nextDouble(rMinA, rMaxA));
   450→
   451→		return repulsionPack(shape, points);
   452→	}
