   454→	/**
   455→	 * Generates a circle packing of a shape using a given collection of
   456→	 * (overlapping) circles.
   457→	 * <p>
   458→	 * Circles in the input should be already bounded by the shape (since repulsion
   459→	 * does not push lonely circles towards the shape, but only repulses overlapping
   460→	 * circles); the intended input is one having circles with lots of overlap
   461→	 * (perhaps seeded within a small rectangle), where they may be repulsed from
   462→	 * each other to fill the shape.
   463→	 * <p>
   464→	 * Repulsion-packing involves iterative pair-repulsion, in which overlapping
   465→	 * circles move away from each other until there is no overlap. A packing is
   466→	 * first computed for the envelope of the shape, and then any circles which do
   467→	 * not overlap with the shape are discarded.
   468→	 * 
   469→	 * @param shape   the shape from which to generate a circle packing
   470→	 * @param circles the collection of circles to pack the shape with, specified as
   471→	 *                PVectors, where .z is the radius (>=1) for each circle
   472→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   473→	 *         the center point and .z represents radius.
   474→	 * @since 1.3.0
   475→	 * @see #repulsionPack(PShape, double, double, long)
   476→	 */
   477→	public static List<PVector> repulsionPack(PShape shape, List<PVector> circles) {
   478→		final Geometry g = fromPShape(shape);
   479→		final Envelope e = g.getEnvelopeInternal();
   480→
   481→		float radiusMin = Float.MAX_VALUE;
   482→		float radiusMax = Float.MIN_VALUE;
   483→		for (PVector circle : circles) {
   484→			radiusMax = Math.max(1f, Math.max(radiusMax, circle.z));
   485→			radiusMin = Math.max(1f, Math.min(radiusMin, circle.z));
   486→		}
   487→
   488→		final RepulsionCirclePack packer = new RepulsionCirclePack(circles, e.getMinX() + radiusMin, e.getMaxX() - radiusMin,
   489→				e.getMinY() + radiusMin, e.getMaxY() - radiusMin, false);
   490→
   491→		final List<PVector> packing = packer.getPacking(); // packing result
   492→
   493→		IndexedPointInAreaLocator pointLocator;
   494→		if (radiusMin == radiusMax) {
   495→			// if every circle same radius, use faster contains check
   496→			pointLocator = new IndexedPointInAreaLocator(g.buffer(radiusMax));
   497→			packing.removeIf(p -> pointLocator.locate(PGS.coordFromPVector(p)) == Location.EXTERIOR);
   498→		} else {
   499→			pointLocator = new IndexedPointInAreaLocator(g);
   500→			IndexedFacetDistance distIndex = new IndexedFacetDistance(g);
   501→			packing.removeIf(p -> {
   502→				// first test whether shape contains circle center point (somewhat faster)
   503→				if (pointLocator.locate(PGS.coordFromPVector(p)) != Location.EXTERIOR) {
   504→					return false;
   505→				}
   506→				return distIndex.distance(PGS.pointFromPVector(p)) > p.z * 0.5;
   507→			});
   508→		}
   509→
   510→		return packing;
   511→	}
