   513→	/**
   514→	 * Generates a tiled circle packing consisting of equal-sized circles arranged
   515→	 * in a square lattice (or grid) bounded by the input shape.
   516→	 * <p>
   517→	 * Circles are included in the packing if they overlap with the given shape.
   518→	 * 
   519→	 * @param shape    the shape from which to generate a circle packing
   520→	 * @param diameter diameter of every circle in the packing
   521→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   522→	 *         the center point and .z represents radius.
   523→	 * @see #hexLatticePack(PShape, double)
   524→	 */
   525→	public static List<PVector> squareLatticePack(PShape shape, double diameter) {
   526→		diameter = Math.max(diameter, 0.1);
   527→		final double radius = diameter / 2;
   528→
   529→		final Geometry g = fromPShape(shape);
   530→		final Envelope e = g.getEnvelopeInternal();
   531→		// buffer the geometry to use InAreaLocator to test circles for overlap (this
   532→		// works because all circles have the same diameter)
   533→		final IndexedPointInAreaLocator pointLocator = new IndexedPointInAreaLocator(g.buffer(radius * 0.95));
   534→		final double w = e.getWidth() + diameter + e.getMinX();
   535→		final double h = e.getHeight() + diameter + e.getMinY();
   536→
   537→		final List<PVector> out = new ArrayList<>();
   538→
   539→		for (double x = e.getMinX(); x < w; x += diameter) {
   540→			for (double y = e.getMinY(); y < h; y += diameter) {
   541→				if (pointLocator.locate(new Coordinate(x, y)) != Location.EXTERIOR) {
   542→					out.add(new PVector((float) x, (float) y, (float) radius));
   543→				}
   544→			}
   545→		}
   546→		return out;
   547→	}
