   549→	/**
   550→	 * Generates a tiled circle packing consisting of equal-sized circles arranged
   551→	 * in a hexagonal lattice bounded by the input shape.
   552→	 * <p>
   553→	 * Circles are included in the packing if they overlap with the given shape.
   554→	 * 
   555→	 * @param shape    the shape from which to generate a circle packing
   556→	 * @param diameter diameter of every circle in the packing
   557→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   558→	 *         the center point and .z represents radius.
   559→	 * @see #squareLatticePack(PShape, double)
   560→	 */
   561→	public static List<PVector> hexLatticePack(PShape shape, double diameter) {
   562→		diameter = Math.max(diameter, 0.1);
   563→		final double radius = diameter / 2d;
   564→
   565→		final Geometry g = fromPShape(shape);
   566→		final Envelope e = g.getEnvelopeInternal();
   567→		/*
   568→		 * Buffer the geometry to use InAreaLocator to test circles for overlap (this
   569→		 * works because all circles have the same diameter).
   570→		 */
   571→		final IndexedPointInAreaLocator pointLocator = new IndexedPointInAreaLocator(g.buffer(radius * 0.95));
   572→		final double w = e.getWidth() + diameter + e.getMinX();
   573→		final double h = e.getHeight() + diameter + e.getMinY();
   574→
   575→		final List<PVector> out = new ArrayList<>();
   576→
   577→		final double z = radius * Math.sqrt(3); // hex distance between successive columns
   578→		double offset = 0;
   579→		for (double x = e.getMinX(); x < w; x += z) {
   580→			offset = (offset == radius) ? 0 : radius;
   581→			for (double y = e.getMinY() - offset; y < h; y += diameter) {
   582→				if (pointLocator.locate(new Coordinate(x, y)) != Location.EXTERIOR) {
   583→					out.add(new PVector((float) x, (float) y, (float) radius));
   584→				}
   585→			}
   586→		}
   587→		return out;
   588→	}
   589→
   590→	/**
   591→	 * Computes the incircle of a triangle; the largest circle contained in a given
   592→	 * triangle.
   593→	 * 
   594→	 * @param t triangle
   595→	 * @return PVector, where x & y represent incenter coordinates, and z represents
   596→	 *         incircle radius.
   597→	 */
   598→	private static PVector inCircle(SimpleTriangle t) {
   599→		final double a = t.getEdgeA().getLength();
   600→		final double b = t.getEdgeB().getLength();
   601→		final double c = t.getEdgeC().getLength();
   602→
   603→		double inCenterX = t.getVertexA().x * a + t.getVertexB().x * b + t.getVertexC().x * c;
   604→		inCenterX /= (a + b + c);
   605→		double inCenterY = t.getVertexA().y * a + t.getVertexB().y * b + t.getVertexC().y * c;
   606→		inCenterY /= (a + b + c);
   607→
   608→		final double s = (a + b + c) / 2; // semiPerimeter
   609→
   610→		final double r = Math.sqrt(((s - a) * (s - b) * (s - c)) / s);
   611→
   612→		return new PVector((float) inCenterX, (float) inCenterY, (float) r);
   613→	}
   614→
   615→	private static PVector centroid(SimpleTriangle t) {
   616→		final Vertex a = t.getVertexA();
   617→		final Vertex b = t.getVertexB();
   618→		final Vertex c = t.getVertexC();
   619→		double x = a.x + b.x + c.x;
   620→		x /= 3;
   621→		double y = a.y + b.y + c.y;
   622→		y /= 3;
   623→		return new PVector((float) x, (float) y);
   624→	}
   625→
   626→	/**
   627→	 * Calculate the distance between two points in 3D space, where each point
   628→	 * represents a circle with (x, y, r) coordinates. This custom metric considers
   629→	 * both the Euclidean distance between the centers of the circles and the
   630→	 * absolute difference of their radii.
   631→	 * <p>
   632→	 * The metric is defined as follows: Given two points A and B, representing
   633→	 * circles centered at (x1, y1) and (x2, y2) with radii r1 and r2 respectively,
   634→	 * the distance is calculated as sqrt((x1 - x2)^2 + (y1 - y2)^2) + |r1 - r2|.
   635→	 * <p>
   636→	 * This metric can be used to find the nearest circle to a given center (x, y)
   637→	 * in a proximity search. To perform the search, use a point (x, y, R) where R
   638→	 * is greater than or equal to the maximum radius of a circle in the proximity
   639→	 * structure.
   640→	 *
   641→	 * @param p1 3D point representing the first circle (x1, y1, r1)
   642→	 * @param p2 3D point representing the second circle (x2, y2, r2)
   643→	 * @return the distance between the two points based on the custom metric
   644→	 */
   645→	private static final PointDistanceFunction circleDistanceMetric = (p1, p2) -> {
   646→		// from https://stackoverflow.com/a/21975136/
   647→		final double dx = p1[0] - p2[0];
   648→		final double dy = p1[1] - p2[1];
   649→		final double dz = p1[2] - p2[2];
   650→
   651→		double euclideanDistance = Math.sqrt(dx * dx + dy * dy);
   652→		double absZDifference = Math.abs(dz);
   653→		return euclideanDistance + absZDifference; // negative if inside
   654→	};
   655→
   656→	/**
   657→	 * A streams filter to remove triangulation triangles that share at least one
   658→	 * edge with the shape edge.
   659→	 */
   660→	private static final Predicate<SimpleTriangle> filterBorderTriangles = t -> t.getContainingRegion() != null
   661→			&& !t.getEdgeA().isConstrainedRegionBorder() && !t.getEdgeB().isConstrainedRegionBorder()
   662→			&& !t.getEdgeC().isConstrainedRegionBorder();
   663→
   664→}
   665→

