    36→/**
    37→ * A simple KD-Tree implementation. 
    38→ * 
    39→ * @author T. Zäschke
    40→ *
    41→ * @param <T> Value type
    42→ */
    43→public class KDTree<T> implements PointIndex<T> {
    44→
    45→	private static final String NL = System.lineSeparator();
    46→
    47→	public static final boolean DEBUG = false;
    48→	
    49→	private final int dims;
    50→	private int size = 0; 
    51→	private int modCount = 0;
    52→	private long nDist1NN = 0;
    53→	private long nDistKNN = 0;
    54→	//During insertion, the tree maintains an invariant that if two points have the
    55→	//same value in any dimension, then one key is never in the 'lower' branch of the other.
    56→	//This allows very efficient look-up because we have to follow only a single path.
    57→	//Unfortunately, removing keys (and moving up keys in the tree) may break this invariant.
    58→	//
    59→	//The cost of breaking the invariant is that there may be two branches that contain the same
    60→	//key. This makes searches more expensive simply because the code gets more complex.
    61→	//
    62→	//One solution to maintain the invariant is to repair the invariant by moving all points 
    63→	//with the same value into the 'upper' part of the point that was moved up. 
    64→	//Identifying these points is relatively cheap, we can do this while searching for 
    65→	//the min/max during removal. However, _moving_ these point may be very expensive.
    66→	//
    67→	//Our (pragmatic) solution is identify when the invariant gets broken.
    68→	//When it is not broken, we use the simple search. If it gets broken, we use the slower search.
    69→	//This is especially useful in scenarios where 'remove()' is not required or where
    70→	//points have never the same values (such as for physical measurements or other experimental results).
    71→	private boolean invariantBroken = false;
    72→	
    73→	private Node<T> root;
    74→	
    75→	private final PointDistanceFunction dist;
    76→	
    77→	public static void main(String ... args) {
