   112→			System.out.println("kNN query: " + Arrays.toString(key));
   113→			QueryIteratorKNN<PointEntryDist<double[]>> iter = tree.queryKNN(key, 1);
   114→			if (!iter.hasNext()) {
   115→				throw new IllegalStateException("kNN() failed: " + Arrays.toString(key));
   116→			}
   117→			double[] answer = iter.next().point();
   118→			if (answer != key && !Arrays.equals(answer, key)) {
   119→				throw new IllegalStateException("Expected " + Arrays.toString(key) + " but got " + Arrays.toString(answer));
   120→			}
   121→		}
   122→
   123→		for (double[] key : point_list) {
   124→//			System.out.println(tree.toStringTree());
   125→			System.out.println("Removing: " + Arrays.toString(key));
   126→			if (!tree.containsExact(key)) {
   127→				throw new IllegalStateException("containsExact() failed: " + Arrays.toString(key));
   128→			}
