   135→	
   136→	private KDTree(int dims, PointDistanceFunction dist) {
   137→		if (DEBUG) {
   138→			System.err.println("Warning: DEBUG enabled");
   139→		}
   140→		this.dims = dims;
   141→		this.dist = dist != null ? dist : PointDistanceFunction.L2;
   142→	}
   143→
   144→	public static <T> KDTree<T> create(int dims) {
   145→		return new KDTree<>(dims, PointDistanceFunction.L2);
   146→	}
   147→	
   148→	public static <T> KDTree<T> create(int dims, PointDistanceFunction dist) {
   149→		return new KDTree<>(dims, dist);
   150→	}
   151→	
   152→	/**
   153→	 * Insert a key-value pair.
   154→	 * @param key the key
   155→	 * @param value the value
   156→	 */
   157→	@Override
   158→	public void insert(double[] key, T value) {
   159→		size++;
   160→		modCount++;
   161→		if (root == null) {
   162→			root = new Node<>(key, value, 0);
   163→			return;
   164→		}
   165→		Node<T> n = root;
   166→		while ((n = n.getClosestNodeOrAddPoint(key, value, dims)) != null);
   167→	}
   168→	
   169→	/**
   170→	 * Check whether a given key exists.
   171→	 * @param key the key to check
   172→	 * @return true iff the key exists
   173→	 */
   174→	public boolean containsExact(double[] key) {
   175→		return findNodeExcat(key, new RemoveResult<>()) != null;
   176→	}
   177→	
   178→	/**
   179→	 * Get the value associates with the key.
   180→	 * @param key the key to look up
   181→	 * @return the value for the key or 'null' if the key was not found
   182→	 */
   183→	@Override
   184→	public T queryExact(double[] key) {
   185→		Node<T> e = findNodeExcat(key, new RemoveResult<>());
   186→		return e == null ? null : e.getValue();
   187→	}
   188→	
   189→	private Node<T> findNodeExcat(double[] key, RemoveResult<T> resultDepth) {
   190→		if (root == null) {
   191→			return null;
   192→		}
   193→		return invariantBroken 
   194→				? findNodeExactSlow(key, root, null, resultDepth) 
   195→						: findNodeExcatFast(key, null, resultDepth);
   196→	} 
   197→
   198→	private Node<T> findNodeExcatFast(double[] key, Node<T> parent, RemoveResult<T> resultDepth) {
   199→		Node<T> n = root;
   200→		do {
   201→			double[] nodeKey = n.getKey();
   202→			double nodeX = nodeKey[n.getDim()];
   203→			double keyX = key[n.getDim()];
   204→			if (keyX == nodeX && Arrays.equals(key, nodeKey)) {
   205→				resultDepth.pos = n.getDim();
   206→				resultDepth.nodeParent = parent;
   207→				return n;
   208→			}
   209→			parent = n;
   210→			n = (keyX >= nodeX) ? n.getHi() : n.getLo();
   211→		} while (n != null);
   212→		return n;
   213→	}
   214→	
   215→	private Node<T> findNodeExactSlow(double[] key, Node<T> n, Node<T> parent, RemoveResult<T> resultDepth) {
   216→		do {
   217→			double[] nodeKey = n.getKey();
   218→			double nodeX = nodeKey[n.getDim()];
   219→			double keyX = key[n.getDim()];
   220→			if (keyX == nodeX) {
   221→				if (Arrays.equals(key, nodeKey)) {
   222→					resultDepth.pos = n.getDim();
   223→					resultDepth.nodeParent = parent;
   224→					return n;
   225→				}
   226→				//Broken invariant? We need to check the 'lower' part as well...
   227→				if (n.getLo() != null) {
   228→					Node<T> n2 = findNodeExactSlow(key, n.getLo(), parent, resultDepth);
   229→					if (n2 != null) {
   230→						return n2;
   231→					}
   232→				}
   233→			}
   234→			parent = n;
   235→			n = (keyX >= nodeX) ? n.getHi() : n.getLo();
   236→		} while (n != null);
   237→		return n;
   238→	}
   239→	
   240→	/**
   241→	 * Remove a key.
   242→	 * @param key key to remove
   243→	 * @return the value associated with the key or 'null' if the key was not found
   244→	 */
   245→	@Override
   246→	public T remove(double[] key) {
   247→		if (root == null) {
   248→			return null;
   249→		}
   250→		
   251→		//find
   252→		RemoveResult<T> removeResult = new RemoveResult<>();
   253→		Node<T> eToRemove = findNodeExcat(key, removeResult);
   254→		if (eToRemove == null) {
   255→			return null;
   256→		}
   257→
   258→		//remove
   259→		modCount++;
   260→		T value = eToRemove.getValue();
   261→		if (eToRemove == root && size == 1) {
   262→			root = null;
   263→			size = 0;
   264→			invariantBroken = false;
   265→		}
   266→		
   267→		//find replacement
   268→		removeResult.nodeParent = null; 
   269→		while (eToRemove != null && !eToRemove.isLeaf()) {
   270→			//recurse
   271→			int pos = removeResult.pos;
   272→			removeResult.node = null; 
   273→			//randomize search direction (modCount)
   274→//			if (((modCount & 0x1) == 0 || eToRemove.getHi() == null) && eToRemove.getLo() != null) {
   275→//				//get replacement from left
   276→//				removeResult.best = Double.NEGATIVE_INFINITY;
   277→//				removeMaxLeaf(eToRemove.getLo(), eToRemove, pos, removeResult);
   278→//			} else if (eToRemove.getHi() != null) {
   279→//				//get replacement from right
   280→//				removeResult.best = Double.POSITIVE_INFINITY;
   281→//				removeMinLeaf(eToRemove.getHi(), eToRemove, pos, removeResult);
   282→//			}
   283→			if (eToRemove.getHi() != null) {
   284→				//get replacement from right
   285→				//This is preferable, because it cannot break the invariant
   286→				removeResult.best = Double.POSITIVE_INFINITY;
   287→				removeMinLeaf(eToRemove.getHi(), eToRemove, pos, removeResult);
   288→			} else if (eToRemove.getLo() != null) {
   289→				//get replacement from left
   290→				removeResult.best = Double.NEGATIVE_INFINITY;
   291→				removeMaxLeaf(eToRemove.getLo(), eToRemove, pos, removeResult);
   292→			}
   293→			eToRemove.setKeyValue(removeResult.node.getKey(), removeResult.node.getValue());
   294→			eToRemove = removeResult.node;
   295→		} 
   296→		//leaf node
   297→		Node<T> parent = removeResult.nodeParent; 
   298→		if (parent != null) {
   299→			if (parent.getLo() == eToRemove) {
   300→				parent.setLeft(null);
   301→			} else if (parent.getHi() == eToRemove) {
   302→				parent.setRight(null);
   303→			} else { 
   304→				throw new IllegalStateException();
   305→			}
   306→		}
   307→		size--;
   308→		return value;
   309→	}
   310→
   311→	private static class RemoveResult<T> {
   312→		Node<T> node = null;
   313→		Node<T> nodeParent = null;
   314→		double best;
   315→		int pos;
   316→	}
   317→	
   318→	private void removeMinLeaf(Node<T> node, Node<T> parent, int pos, RemoveResult<T> result) {
   319→		//Split in 'interesting' dimension
   320→		if (pos == node.getDim()) {
   321→			//We strictly look for leaf nodes with left==null
   322→			// -> left!=null means the left child is at least as small as the current node
   323→			if (node.getLo() != null) {
   324→				removeMinLeaf(node.getLo(), node, pos, result);
   325→			} else if (node.getKey()[pos] <= result.best) {
   326→				result.node = node;
   327→				result.nodeParent = parent;
   328→				result.best = node.getKey()[pos];
   329→				result.pos = node.getDim();
   330→			}
   331→		} else {
   332→			//split in any other dimension.
   333→			//First, check local key. 
   334→			double localX = node.getKey()[pos];
   335→			if (localX <= result.best) {
   336→				result.node = node;
   337→				result.nodeParent = parent;
   338→				result.best = localX;
   339→				result.pos = node.getDim();
   340→			}
   341→			if (node.getLo() != null) {
   342→				removeMinLeaf(node.getLo(), node, pos, result);
   343→			}
   344→			if (node.getHi() != null) {
   345→				removeMinLeaf(node.getHi(), node, pos, result);
   346→			}
   347→		}
   348→	}
   349→	
   350→	private void removeMaxLeaf(Node<T> node, Node<T> parent, int pos, RemoveResult<T> result) {
   351→		//Split in 'interesting' dimension
   352→		if (pos == node.getDim()) {
   353→			//We strictly look for leaf nodes with left==null
   354→			if (node.getHi() != null) {
   355→				removeMaxLeaf(node.getHi(), node, pos, result);
   356→			} else if (node.getKey()[pos] >= result.best) {
   357→				result.node = node;
   358→				result.nodeParent = parent;
   359→				result.best = node.getKey()[pos];
   360→				result.pos = node.getDim();
   361→				invariantBroken |= result.best == node.getKey()[pos];
   362→			}
   363→		} else {
   364→			//split in any other dimension.
   365→			//First, check local key. 
   366→			double localX = node.getKey()[pos];
   367→			if (localX >= result.best) {
   368→				result.node = node;
   369→				result.nodeParent = parent;
   370→				result.best = localX;
   371→				result.pos = node.getDim();
   372→				invariantBroken |= result.best == localX;
   373→			}
   374→			if (node.getLo() != null) {
   375→				removeMaxLeaf(node.getLo(), node, pos, result);
   376→			}
   377→			if (node.getHi() != null) {
   378→				 removeMaxLeaf(node.getHi(), node, pos, result);
   379→			}
   380→		}
   381→	}
   382→	
   383→	/**
   384→	 * Reinsert the key.
   385→	 * @param oldKey old key
   386→	 * @param newKey new key
   387→	 * @return the value associated with the key or 'null' if the key was not found.
   388→	 */
   389→	@Override
   390→	public T update(double[] oldKey, double[] newKey) {
   391→		if (root == null) {
   392→			return null;
   393→		}
   394→		T value = remove(oldKey);
   395→		insert(newKey, value);
   396→		return value;
   397→	}
   398→	
   399→	/**
   400→	 * Get the number of key-value pairs in the tree.
   401→	 * @return the size
   402→	 */
   403→	@Override
   404→	public int size() {
   405→		return size;
   406→	}
   407→
   408→	/**
   409→	 * Removes all elements from the tree.
   410→	 */
   411→	@Override
   412→	public void clear() {
   413→		size = 0;
   414→		root = null;
   415→		invariantBroken = false;
   416→		modCount++;
   417→	}
   418→
   419→	/**
   420→	 * Query the tree, returning all points in the axis-aligned rectangle between 'min' and 'max'.
   421→	 * @param min lower left corner of query
   422→	 * @param max upper right corner of query
   423→	 * @return all entries in the rectangle
   424→	 */
   425→	@Override
   426→	public KDIterator<T> query(double[] min, double[] max) {
   427→		return new KDIterator<>(this, min, max);
   428→	}
   429→
   430→	static boolean isEnclosed(double[] point, double[] min, double[] max) {
   431→		for (int i = 0; i < point.length; i++) {
   432→			if (point[i] < min[i] || point[i] > max[i]) {
   433→				return false;
   434→			}
   435→		}
   436→		return true;
   437→	}
   438→
   439→	private double distance(double[] p1, double[] p2) {
   440→		return dist.dist(p1, p2);
   441→	}
   442→	
   443→	/**
   444→	 * 1-nearest neighbor query.
   445→	 * @param center The point for which the nearest neighbors are requested
   446→	 * @return Nearest neighbor
   447→	 */
   448→	public KDEntryDist<T> nnQuery(double[] center) {
   449→		if (root == null) {
   450→    		return null;
   451→		}
   452→    	KDEntryDist<T> candidate = new KDEntryDist<>(null, Double.POSITIVE_INFINITY);
   453→   		rangeSearch1NN(root, center, candidate, Double.POSITIVE_INFINITY);
   454→    	return candidate;
   455→    }
   456→
   457→    private double rangeSearch1NN(Node<T> node, double[] center, 
   458→    		KDEntryDist<T> candidate, double maxRange) {
   459→    	int pos = node.getDim();
   460→    	if (node.getLo() != null && (center[pos] < node.getKey()[pos] || node.getHi() == null)) {
   461→        	//go down
   462→    		maxRange = rangeSearch1NN(node.getLo(), center, candidate, maxRange);
   463→        	//refine result
   464→    		if (center[pos] + maxRange >= node.getKey()[pos]) {
   465→    			maxRange = addCandidate(node, center, candidate, maxRange);
   466→        		if (node.getHi() != null) {
   467→        			maxRange = rangeSearch1NN(node.getHi(), center, candidate, maxRange);
   468→        		}
   469→    		}
   470→    	} else if (node.getHi() != null) {
   471→        	//go down
   472→    		maxRange = rangeSearch1NN(node.getHi(), center, candidate, maxRange);
   473→        	//refine result
   474→    		if (center[pos] <= node.getKey()[pos] + maxRange) {
   475→    			maxRange = addCandidate(node, center, candidate, maxRange);
   476→        		if (node.getLo() != null) {
   477→        			maxRange = rangeSearch1NN(node.getLo(), center, candidate, maxRange);
   478→        		}
   479→    		}
   480→    	} else {
   481→    		//leaf -> first (probably best) match!
   482→    		maxRange = addCandidate(node, center, candidate, maxRange);
   483→    	}
   484→    	return maxRange;
   485→    }
   486→        
   487→    private double addCandidate(Node<T> node, double[] center, 
   488→    		final KDEntryDist<T> candidate, double maxRange) {
   489→    	nDist1NN++;
   490→    	double dist = distance(center, node.getKey());
   491→    	if (dist >= maxRange) {
   492→    		//don't add if too far away
   493→    		//don't add if we already have an equally good result
   494→    		return maxRange;
   495→    	}
   496→    	candidate.set(node, dist);
   497→    	return dist;
   498→    }
   499→	
   500→	public List<KDEntryDist<T>> knnQuery(double[] center, int k) {
   501→		if (root == null) {
   502→    		return Collections.emptyList();
   503→		}
   504→    	ArrayList<KDEntryDist<T>> candidates = new ArrayList<>(k);
   505→   		rangeSearchKNN(root, center, candidates, k, Double.POSITIVE_INFINITY);
   506→    	return candidates;
   507→    }
   508→
   509→    private double rangeSearchKNN(Node<T> node, double[] center, 
   510→    		ArrayList<KDEntryDist<T>> candidates, int k, double maxRange) {
   511→    	int pos = node.getDim();
   512→    	if (node.getLo() != null && (center[pos] < node.getKey()[pos] || node.getHi() == null)) {
   513→        	//go down
   514→    		maxRange = rangeSearchKNN(node.getLo(), center, candidates, k, maxRange);
   515→        	//refine result
   516→    		if (center[pos] + maxRange >= node.getKey()[pos]) {
   517→    			maxRange = addCandidate(node, center, candidates, k, maxRange);
   518→        		if (node.getHi() != null) {
   519→        			maxRange = rangeSearchKNN(node.getHi(), center, candidates, k, maxRange);
   520→        		}
   521→    		}
   522→    	} else if (node.getHi() != null) {
   523→        	//go down
   524→    		maxRange = rangeSearchKNN(node.getHi(), center, candidates, k, maxRange);
   525→        	//refine result
   526→    		if (center[pos] <= node.getKey()[pos] + maxRange) {
   527→    			maxRange = addCandidate(node, center, candidates, k, maxRange);
   528→        		if (node.getLo() != null) {
   529→        			maxRange = rangeSearchKNN(node.getLo(), center, candidates, k, maxRange);
   530→        		}
   531→    		}
   532→    	} else {
   533→    		//leaf -> first (probably best) match!
   534→    		maxRange = addCandidate(node, center, candidates, k, maxRange);
   535→    	}
   536→    	return maxRange;
   537→    }
   538→    
   539→	
   540→    private static final Comparator<KDEntryDist<?>> compKnn =  
   541→    		(KDEntryDist<?> point1, KDEntryDist<?> point2) -> {
   542→    			double deltaDist = point1.dist() - point2.dist();
   543→    			return deltaDist < 0 ? -1 : (deltaDist > 0 ? 1 : 0);
   544→    		};
   545→
   546→    
   547→    private double addCandidate(Node<T> node, double[] center, 
   548→    		ArrayList<KDEntryDist<T>> candidates, int k, double maxRange) {
   549→    	nDistKNN++;
   550→    	//add ?
   551→    	double dist = distance(center, node.getKey());
   552→    	if (dist > maxRange) {
   553→    		//don't add if too far away
   554→    		return maxRange;
   555→    	}
   556→    	if (dist == maxRange && candidates.size() >= k) {
   557→    		//don't add if we already have enough equally good results.
   558→    		return maxRange;
   559→    	}
   560→    	KDEntryDist<T> cand;
   561→    	if (candidates.size() >= k) {
   562→    		cand = candidates.remove(k - 1);
   563→    		cand.set(node, dist);
   564→    	} else {
   565→    		cand = new KDEntryDist<>(node, dist);
   566→    	}
   567→    	int insertionPos = Collections.binarySearch(candidates, cand, compKnn);
   568→    	insertionPos = insertionPos >= 0 ? insertionPos : -(insertionPos+1);
   569→    	candidates.add(insertionPos, cand);
   570→    	return candidates.size() < k ? maxRange : candidates.get(candidates.size() - 1).dist();
   571→    }
   572→    
   573→	
   574→    private static class KDQueryIteratorKNN<T> implements QueryIteratorKNN<PointEntryDist<T>> {
   575→
   576→    	private Iterator<? extends PointEntryDist<T>> it;
   577→    	private final KDTree<T> tree;
   578→    	
   579→		public KDQueryIteratorKNN(KDTree<T> tree, double[] center, int k) {
   580→			this.tree = tree;
   581→			reset(center, k);
   582→		}
   583→
   584→		@Override
   585→		public boolean hasNext() {
   586→			return it.hasNext();
   587→		}
   588→
   589→		@Override
   590→		public PointEntryDist<T> next() {
   591→			return it.next();
   592→		}
   593→
   594→		@Override
   595→		public KDQueryIteratorKNN<T> reset(double[] center, int k) {
   596→			it = tree.knnQuery(center, k).iterator();
   597→			return this;
   598→		}
   599→    }
   600→    
   601→    /**
   602→	 * Returns a printable list of the tree.
   603→	 * @return the tree as String
   604→	 */
   605→    @Override
   606→	public String toStringTree() {
   607→		StringBuilder sb = new StringBuilder();
   608→		if (root == null) {
   609→			sb.append("empty tree");
   610→		} else {
   611→			toStringTree(sb, root, 0);
   612→		}
   613→		return sb.toString();
   614→	}
   615→	
   616→	private void toStringTree(StringBuilder sb, Node<T> node, int depth) {
   617→		String prefix = "";
   618→		for (int i = 0; i < depth; i++) {
   619→			prefix += ".";
   620→		}
   621→		//sb.append(prefix + " d=" + depth + NL);
   622→		prefix += " ";
   623→		if (node.getLo() != null) {
   624→			toStringTree(sb, node.getLo(), depth+1);
   625→		}
   626→		sb.append(prefix + Arrays.toString(node.point()));
   627→		sb.append(" v=" + node.value());
   628→		sb.append(" l/r=");
   629→		sb.append(node.getLo() == null ? null : Arrays.toString(node.getLo().point()));
   630→		sb.append("/");
   631→		sb.append(node.getHi() == null ? null : Arrays.toString(node.getHi().point()));
   632→		sb.append(NL);
   633→		if (node.getHi() != null) {
   634→			toStringTree(sb, node.getHi(), depth+1);
   635→		}
   636→	}
   637→	
   638→	@Override
   639→	public String toString() {
   640→		return "KDTree;size=" + size + 
   641→				";DEBUG=" + DEBUG + 
   642→				";DistFn=" + PointDistanceFunction.getName(dist) +
   643→				";center=" + (root==null ? "null" : Arrays.toString(root.getKey()));
   644→	}
   645→	
   646→	@Override
   647→	public KDStats getStats() {
   648→		KDStats s = new KDStats(this);
   649→		if (root != null) {
   650→			root.checkNode(s, 0);
   651→		}
   652→		return s;
   653→	}
   654→	
   655→	/**
   656→	 * Statistics container class.
   657→	 */
   658→	public static class KDStats extends Stats {
   659→		public KDStats(KDTree<?> tree) {
   660→			super(tree.nDist1NN + tree.nDistKNN, tree.nDist1NN, tree.nDistKNN);
   661→		}
   662→	}
   663→
   664→	@Override
   665→	public int getDims() {
   666→		return dims;
   667→	}
   668→
   669→	@Override
   670→	public QueryIterator<PointEntry<T>> iterator() {
   671→		if (root == null) {
   672→			return query(new double[dims], new double[dims]);
   673→		}
   674→		//return query(root.);
   675→		//TODO
   676→		throw new UnsupportedOperationException();
   677→	}
   678→
   679→	@Override
   680→	public KDEntryDist<T> query1NN(double[] center) {
   681→		return nnQuery(center);
   682→	}
   683→
   684→	@Override
   685→	public QueryIteratorKNN<PointEntryDist<T>> queryKNN(double[] center, int k) {
   686→		return new KDQueryIteratorKNN<>(this, center, k);
   687→	}
   688→
   689→	@Override
   690→	public int getNodeCount() {
   691→		return getStats().getNodeCount();
   692→	}
   693→
   694→	@Override
   695→	public int getDepth() {
   696→		return getStats().getMaxDepth();
   697→	}
   698→	
   699→	Node<T> getRoot() {
   700→		return root;
   701→	}
   702→}
