    78→	private static final boolean NEAREST_ANCESTOR = true;
    79→	
    80→	private final double BASE;
    81→	private final double LOG_BASE;
    82→	
    83→	private final PointDistanceFunction dist;
    84→
    85→	private long nDistCalc = 0;
    86→	private long nDist1NN = 0;
    87→	private long nDistKNN = 0;
    88→	
    89→	private final double log13(double n) {
    90→		//log_b(n) = log_e(n) / log_e(b)
    91→		return Math.log(n) / LOG_BASE;
    92→	}
    93→	
    94→	private CoverTree(int nDims, double base, PointDistanceFunction dist) {
    95→		this.dims = nDims;
    96→		this.BASE = base;
    97→		this.LOG_BASE = Math.log(BASE);
    98→		this.dist = dist != null ? dist : PointDistanceFunction.L2;
    99→	}
   100→		
   101→	public static <T> Point<T> create(double[] point, T value) {
   102→		return new Point<>(point, value);
   103→	}
   104→
   105→	public static <T> CoverTree<T> create(int nDims) {
   106→		return new CoverTree<>(nDims, DEFAULT_BASE, PointDistanceFunction.L2);
   107→	}
   108→	
   109→	public static <T> CoverTree<T> create(int nDims, double base, PointDistanceFunction dist) {
   110→		return new CoverTree<>(nDims, base, dist);
   111→	}
   112→	
   113→	public static <T> CoverTree<T> create(Point<T>[] data, double base, 
   114→			PointDistanceFunction distFn) {
   115→		if (data == null || data.length == 0) {
   116→			throw new IllegalStateException("Bulk load with empty data no possible.");
   117→		}
   118→		CoverTree<T> tree = new CoverTree<>(data[0].point().length, base, distFn);
   119→		if (data.length == 1) {
   120→			tree.root = new Node<>(data[0], 0);
   121→			tree.nEntries++;
   122→			return tree;
   123→		}
   124→		
   125→		//The point of bulkload is (currently) only to initialize the tree with a 
   126→		//suitable 'level' and 'root', which should avoid any problems with having 
   127→		//to pull up leaves to replace the root. Bulkloading thus allows a BASE < 2.0 .
   128→		
   129→		Point<T> newRoot = data[0];
   130→		Point<T> mostDistantPoint = data[1];
   131→		double largestDistance = tree.d(newRoot, mostDistantPoint); 
   132→		for (int i = 2; i < data.length; i++) {
   133→			Point<T> x = data[i];
   134→			double dist = tree.d(newRoot, x);
   135→			if (dist > largestDistance) {
   136→				largestDistance = dist;
   137→				mostDistantPoint = x;
   138→			}
   139→		}
   140→		
   141→		int requiredLevel = (int) (tree.log13(largestDistance) + 1);
   142→		tree.root = new Node<T>(data[0], requiredLevel);
   143→		//TODO insert farthest point as second point?
   144→		
   145→		for (int i = 1; i < data.length; i++) {
   146→			Node<T> x = new Node<>(data[i], -1);
   147→			tree.insert(tree.root, x);
   148→		}
   149→
   150→		tree.nEntries = data.length;
   151→
   152→		return tree;
   153→	}
