   232→	@Override
   233→	public void insert(double[] key, T value) {
   234→		//System.out.println("Inserting(" + nEntries + "): " + Arrays.toString(key));
   235→		Node<T> x = new Node<>(new Point<>(key, value), -1);
   236→		if (root == null) {
   237→			root = x.initLevel(0);
   238→			nEntries++;
   239→			return;
   240→		}
   241→		if (!root.hasChildren()) {
   242→			double dist = d(root, x);
   243→			//initialize levels from current distance
   244→			int level = (int) log13(dist);
   245→			root.setLevel(level + 1);
   246→			Node<T> q = x.initLevel(level);
   247→			root.addChild(q, dist);
   248→			nEntries++;
   249→			return;
   250→		}
   251→		insert(root, x);
   252→		nEntries++;
   253→	}
