   255→	private void insert(Node<T> p, Node<T> x) {
   256→//		Algorithm 2 Simplified cover tree insertion
   257→//		function insert(cover tree p, data point x)
   258→//		1: if d(p;x) > covdist(p) then
   259→//		2: while d(p;x) > 2covdist(p) do
   260→//		3: Remove any leaf q from p
   261→//		4: p0  tree with root q and p as only child
   262→//		5: p  p0
   263→//		6: return tree with x as root and p as only child
   264→//		7: return insert (p,x)
   265→		double distPX = d(p,x); 
   266→		if (distPX > covdist(p)) {
   267→			//TODO reuse distPX in first iteration?!?
   268→			//while (d(p.point(), x) > BASE*covdist(p)) {
   269→			//TODO the above is WRONG! For example it does not work with [2,3],[5,4],[9,6],
   270→			//     resulting in a covDist([9,6]) that does not cover [2,3]
   271→			//  while (distPX + covdist(p)> BASE*covdist(p)) {
   272→			//Even better: we could use:
   273→			//  while (distPX + maxdist(p)> BASE*covdist(p)) {
   274→			//TODO above fix can be simplified:
   275→			while (distPX > (BASE-1)*covdist(p)) {
   276→				//3: Remove any leaf q from p
   277→				Node<T> q = p.removeAnyLeaf();
   278→				//4: p0 = tree with root q and p as only child
   279→				Node<T> p0 = q;
   280→				q.setLevel(p.getLevel() + 1);
   281→				q.addChild(p, d(q, p));
   282→				//5: p  p0
   283→				p = p0;
   284→				distPX = d(p,x);
   285→			}
   286→			//return tree with x as root and p as only child;
   287→			Node<T> newRoot = x.initLevel(p.getLevel() + 1);
   288→			newRoot.addChild(p, distPX);
   289→			//TODO set in caller?
   290→			this.root = newRoot;
   291→			return;
   292→		}
   293→		if (NEAREST_ANCESTOR) {
   294→			insert2NA(p,x, distPX);
   295→		} else {
   296→			insert2(p, x, distPX);
   297→		}
   298→	}
