   300→	private Node<T> insert2(Node<T> p, Node<T> x, double distPX) { 
   301→//		function insert (cover tree p, data point x)
   302→//		prerequisites: d(p;x) <= covdist(p)
   303→//		1: for q 2 children(p) do
   304→//		2: if d(q;x) <= covdist(q) then
   305→//		3: q0  insert (q;x)
   306→//		4: p0   p with child q replaced with q0
   307→//		5: return p0
   308→//		6: return p with x added as a child
   309→
   310→		//1: for q : children(p) do
   311→		ArrayList<Node<T>> children = p.getOrCreateChildren();
   312→		double covDistQ = children.isEmpty()? 0 : covdist(children.get(0));
   313→		for (int i = 0; i < children.size(); i++) {
   314→			Node<T> q = children.get(i);
   315→			//2: if d(q;x) <= covdist(q) then
   316→			double distQX = d(q, x); 
   317→			if (distQX <= covDistQ) {
   318→				//3: q0  insert (q;x)
   319→				Node<T> qNew = insert2(q, x, distQX);
   320→				//4: p0   p with child q replaced with q0
   321→				if (qNew != q) {
   322→					p.replaceChild(i, qNew);
   323→				}
   324→				//5: return p0
   325→				p.adjustMaxDist(distPX);
   326→				return p;
   327→			}
   328→		}
   329→		//6: return p with x added as a child
   330→		p.addChild(x.initLevel(p.getLevel() - 1), distPX);
   331→		return p;
   332→//		return rebalance(p, x);
   333→	}
