   335→	/**
   336→	 * Nearest ancestor insert
   337→	 * @param p
   338→	 * @param x
   339→	 * @param distPX
   340→	 * @return
   341→	 */
   342→	private Node<T> insert2NA(Node<T> p, Node<T> x, double distPX) { 
   343→//		function insert (cover tree p, data point x)
   344→//		prerequisites: d(p;x) <= covdist(p)
   345→
   346→		//insert into closest child!
   347→		
   348→		//1: for q : children(p) do
   349→		ArrayList<Node<T>> children = p.getOrCreateChildren();
   350→		double covDistQ = covDist(p.getLevel() - 1);
   351→		Node<T> best = null;
   352→		double distBest = Double.MAX_VALUE;
   353→		int posBest = -1;
   354→		for (int i = 0; i < children.size(); i++) {
   355→			Node<T> q = children.get(i);
   356→			//2: if d(q;x) <= covdist(q) then
   357→			double distQX = d(q, x); 
   358→			if (distQX <= covDistQ && distQX < distBest) {
   359→				distBest = distQX;
   360→				best = q;
   361→				posBest = i;
   362→			}
   363→		}
   364→		if (best != null) {
   365→			Node<T> q = best;
   366→			double distQX = distBest;
   367→			int i = posBest;
   368→			//3: q0  insert (q;x)
   369→			Node<T> qNew = insert2NA(q, x, distQX);
   370→			//4: p0   p with child q replaced with q0
   371→			if (qNew != q) {
   372→				p.replaceChild(i, qNew);
   373→			}
   374→			//5: return p0
   375→			p.adjustMaxDist(distPX);
   376→			return p;
   377→		}
   378→		//6: return p with x added as a child
   379→//		p.addChild(x.initLevel(p.getLevel() - 1), distPX);
   380→//		return p;
   381→		return rebalanceTZ(p, x, distPX);
   382→	}
