   384→	private Node<T> rebalanceTZ(Node<T> p, Node<T> x, double distPX) {
   385→		//Rebalance to ensure the nearest-ancestor invariant:
   386→		//1) Find all nodes 'q' whose covdist && mindist overlaps with the new node x
   387→		//2) For all 'q' traverse all subnode 'r' and check if:
   388→		//   a) Parent-dist(r) > dist(x,q)-covdist(x)
   389→		//   b1) (1st level): dist(x,r) < parentDist(r)
   390→		//   b2)  
   391→		
   392→		//Remember the nearest-ancestor invariants only refers to the IMMEDIATE
   393→		//ancestor!
   394→		//Convention: 'x' is a new node that is inserted into a node 'p'. The other
   395→		//children or 'p' are named 'q'. Any children of 'q' or 'x' are named 'r'.
   396→		//Any children (descendants?) of any 'r' a named 's'.
   397→		//Implications of invariant: 
   398→		//- If we childnode r of q to x, we try to keep it on the same level,
   399→		//  which means we can move it together with all it's children.
   400→		//  -> Problem if we move r1 from q1 and r2 from q2 into x,
   401→		//     there is no guarantee that r1 and r2 have a minimum distance of
   402→		//     cov-dist, in other words they may need 'merging'!
   403→		//     TODO is that geometrically possible?
   404→		//  -> Merging entails a bigger problem: 
   405→		//     If we reinsert all the children (r1, r2, ..) into x, on of the
   406→		//     subchildren s of r, may be inserted directly into 'x', even though
   407→		//     x may not be it's nearest ancestor (that can only happen for children
   408→		//     or r's, because ...)
   409→		//Solution: 
   410→		//  - r's can be directly re-inserted into x, but any children of r's
   411→		//     need to be queued and reinserted a root level....
   412→		//  - Reinsertion of children r of q into x is fine as long as none 
   413→		//    of the reinserted r's overlap (more precisely if they do not have children
   414→		//    that could be in any other r of x.
   415→		//  - Optimization: Even if an r cannot be reinserted into x, it's 's' may be 
   416→		//    reinsertable if there is only one matching r in x.
   417→		//  - In other words, any new r of x that overlaps with any 
   418→		//  In orher words: Direct reinsertion is fine, as long as the new level is equal 
   419→		//  or lower that the previous level.
   420→		//
   421→		//Algorithm for reinsertion:
   422→		//- if there is no overlapping r1 in x: Insert r2 including all children
   423→		//- If there is an overlapping r1, add r2 to List of reinsertables.
   424→		//  for every child s or r2, check whether there is only one matching r in x.
   425→		//  - if yes: insert s into that r. Then: recurse for children of s or add to reinsertables 
   426→		//  - if no: add 's' and all it's children to reinsertables.
   427→		//All reinsertion can be done directly into 'p' (parent of q and x) because
   428→		//we know that there are at least two nodes in p (x and q) that can contain the
   429→		//moved node. Insert directly into 'x' would be good for all direct children of
   430→		//'q' because we know that 'x' is the closest ancestor. For sub-children of 'q'
   431→		//we cannot guarantee that. If one of these subchildren can be reinsertedinto
   432→		//any r of x, it would be fine. But if it is inserted directly in 'x', we would need
   433→		//to verify that there is no other q in p that would be a better ancestor.
   434→		//However, if we reinsert these subchildren in to 'p', we know that there
   435→		//is at least one 'q' (namely it's original parent) that contain it, so there
   436→		//is no need that 'p' is the closest ancestor because 'p' would never be a direct ancestor.
   437→		//In short: Insert into 'x' if possible, otherwise reinsert into 'p'.
   438→		ArrayList<Node<T>> reinsert = null;
   439→		//init, because we may use (insert, covdist, ..) this node before we add it to p.
   440→		x.initLevel(p.getLevel() - 1);
   441→		if (p.hasChildren()) {
   442→			ArrayList<Node<T>> children = p.getChildren();
   443→			double covDist = covDist(p.getLevel() - 1);
   444→			//Check all siblings q of x whether they may contain point that need
   445→			//to be reassigned. 'q' itself cannot require reassignment. 
   446→			for (int i = 0; i < children.size(); i++) {
   447→				Node<T> q = children.get(i);
   448→				if (q.hasChildren()) {
   449→					double distQX = d(q, x); 
   450→					if (distQX <= 2*covDist
   451→							&& distQX <= covDist + q.maxdist(this)) {
   452→						reinsert = (reinsert != null) ? reinsert : new ArrayList<>();
   453→						rebalanceSub(x, q, reinsert, distQX);
   454→					}
   455→				}
   456→			}
   457→		}
   458→		p.addChild(x, distPX);
   459→		if (reinsert != null) {
   460→			for (int i = 0; i < reinsert.size(); i++) {
   461→				Node<T> q = reinsert.get(i);
   462→				insert2NA(p, q, distPX);
   463→			}
   464→		}
   465→		return p;
   466→	}
