   468→	/**
   469→	 * 
   470→	 * @param x New ancestor
   471→	 * @param q Current ancestor
   472→	 * @param reinsert resinsertion queue 
   473→	 */
   474→	private void rebalanceSub(Node<T> x, Node<T> q, ArrayList<Node<T>> reinsert,
   475→			double distQX) {
   476→		if (q.hasChildren()) {
   477→			ArrayList<Node<T>> children = q.getChildren();
   478→			for (int i = 0; i < children.size(); i++) {
   479→				Node<T> r = children.get(i);
   480→				double distRQ = r.getDistanceToParent();
   481→				if (distRQ*2 > distQX) {
   482→					double distRX = d(r, x);
   483→					if (distRX < distRQ) {
   484→						//okay, needs reinsertion
   485→						q.removeChild(i--);
   486→						reinsert(x, r, reinsert, distRX);
   487→					}
   488→				}
   489→			}
   490→		}
   491→	}
