   493→	private void reinsert(Node<T> x, Node<T> rNew, ArrayList<Node<T>> reinsertLater,
   494→			double distRX) {
   495→		ArrayList<Node<T>> children = x.getOrCreateChildren();
   496→		double covDistR = covdist(rNew);
   497→		for (int i = 0; i < children.size(); i++) {
   498→			Node<T> rx = children.get(i);
   499→			double distRxRNew = d(rx, rNew);
   500→			//Overlap of covers?
   501→			if (distRxRNew < 2*covDistR) {
   502→				if (distRxRNew < covDistR) {
   503→					//reinsert rNew into rX: not possible, reinsert in parent
   504→					rNew.clearAndRemoveAllChildren(reinsertLater);
   505→					reinsertLater.add(rNew);
   506→					return;
   507→				} else if (rNew.maxdist(this) > distRxRNew-covDistR) {
   508→					//rNew's children overlap with rX: 
   509→					//reinsert rNew and reinsert children into parent.
   510→					//But we need to keep checking other rX.
   511→					rNew.clearAndRemoveAllChildren(reinsertLater);
   512→				}
   513→			} 
   514→		}
   515→		if (distRX + rNew.maxdist(this) > covdist(x)) {
   516→			//TODO only clear those that violate the limit
   517→			rNew.clearAndRemoveAllChildren(reinsertLater);
   518→		}
   519→		x.addChild(rNew, distRX);
   520→	}
