   522→	private Node<T> rebalance(Node<T> p, Node<T> x) {
   523→//  	function rebalance(cover trees p, data point x)
   524→//  	prerequisites: x can be added as a child of p without violating
   525→//      the covering or separating invariants
   526→//		1: create tree x0 with root node x at level level(p)􀀀1 x0
   527→//		contains no other points
   528→//		2: p0   p
   529→//		3: for q 2 children(p) do
   530→//		4: (q0;moveset; stayset) rebalance (p;q;x)
   531→//		5: p0   p0 with child q replaced with q0
   532→//		6: for r 2 moveset do
   533→//		7: x0  insert(x0; r)
   534→//		8: return p0 with x0 added as a child
   535→	
   536→		//	1: create tree x0 with root node x at level level(p)-1 x0
   537→		//	contains no other points
   538→		Node<T> x0 = x.initLevel(p.getLevel() - 1); 
   539→		//	2: p0   p
   540→		Node<T> p0 = p;
   541→		//	3: for q 2 children(p) do
   542→		if (p.hasChildren()) {
   543→			ArrayList<Node<T>> children = p.getChildren();
   544→			ArrayList<Node<T>> moveSet = new ArrayList<>();
   545→			ArrayList<Node<T>> staySet = new ArrayList<>();
   546→			for (int i = 0; i < children.size(); i++) {
   547→				Node<T> q = children.get(i);
   548→				//	4: (q0;moveset; stayset) rebalance (p;q;x)
   549→				moveSet.clear();
   550→				staySet.clear();
   551→				Node<T> q0 = rebalance(p, q, x, moveSet, staySet);
   552→				//	5: p0   p0 with child q replaced with q0
   553→				if (q0 != null) {
   554→					p0.replaceChild(i, q0);
   555→				}
   556→				q0.adjustMaxDist(d(p0, q0));
   557→				//TODO adjust max?!?!
   558→				//	6: for r 2 moveset do
   559→				for (int j = 0; j < moveSet.size(); j++) {
   560→					//	7: x0  insert(x0; r)
   561→					//x0 = insert(x0, moveSet.get(j)); //TODO report!
   562→					x0 = insert2(x0, moveSet.get(j), d(x0, moveSet.get(j)));
   563→				}
   564→			}
   565→		}
   566→		//	8: return p0 with x0 added as a child
   567→		p0.addChild(x0, d(p0, x0));
   568→		return p0;
   569→	}
