   693→	private Point<T> queryExact(Node<T> p, double[] x) {
   694→		if (Arrays.equals(p.point().point(), x)) {
   695→			return p.point();
   696→		}
   697→		double distP = d(p.point(), x);
   698→		if (distP > p.maxdist(this)) {
   699→			return null;
   700→		}
   701→
   702→		ArrayList<Node<T>> children = p.getChildren();
   703→		for (int i = 0; i < children.size(); i++) {
   704→			Node<T> q = children.get(i);
   705→			Point<T> result = queryExact(q, x);
   706→			if (result != null) {
   707→				return result;
   708→			}
   709→		}
   710→		return null;
   711→	}
