   714→	public QueryIterator<? extends PointEntry<T>> iterator() {
   715→		// TODO Auto-generated method stub
   716→		throw new UnsupportedOperationException();
   717→		//return null;
   718→	}
   719→
   720→	@Override
   721→	public QueryIterator<PointEntry<T>> query(double[] min, double[] max) {
   722→		// TODO Auto-generated method stub
   723→		throw new UnsupportedOperationException();
   724→		//return null;
   725→	}
   726→	
   727→	@Override
   728→	public PointEntryDist<T> query1NN(double[] center) {
   729→		if (root == null) {
   730→			return null;
   731→		}
   732→		//TODO avoid all these object creations
   733→		Point<T> x = new Point<>(center, null);
   734→		double distPX = d(root.point(), center);
   735→		nDist1NN++;
   736→		PointDist<T> y = new PointDist<>(root.point().point(), root.point().value(), distPX);
   737→		findNearestNeighbor(root, x, y, distPX);
   738→		return y;
   739→	}
   740→
   741→	private void findNearestNeighbor(Node<T> p, Point<T> x, final PointDist<T> y, 
   742→			double distPX) {
   743→//		Algorithm 1 Find nearest neighbor
   744→//		function findNearestNeighbor(cover tree p, query
   745→//		point x, nearest neighbor so far y)
   746→//		1: if d(p;x) < d(y;x) then
   747→//		2: y  p
   748→//		3: for each child q of p sorted by distance to x do
   749→//		4: if d(y;x) > d(y;q)-maxdist(q) then
   750→//		5: y findNearestNeighbor(q;x;y)
   751→//		6: return y
   752→		if (distPX < y.dist()) {
   753→			y.set(p.point(), distPX);
   754→		}
   755→
   756→		if (p.hasChildren()) {
   757→			ArrayList<Node<T>> children = p.getChildren();
   758→			for (int i = 0; i < children.size(); i++) {
   759→				Node<T> q = children.get(i);
   760→				
   761→				//Exclude children that are (compared to x) too close to the node or too far away
   762→				//to contain any useful points.
   763→				double distPQ = q.getDistanceToParent();
   764→				if (distPQ+q.maxdist(this) < distPX-y.dist()
   765→						|| distPQ-q.maxdist(this)> distPX+y.dist()) {
   766→					continue;
   767→				}
   768→
   769→				//TODO report to authors: use d(y;x) > d(_X_;q)-maxdist(q)
   770→				double distQX = d(x, q.point());
   771→				nDist1NN++;
   772→				if (y.dist() > (distQX - q.maxdist(this))) {
   773→					findNearestNeighbor(q, x, y, distQX);
   774→				}
   775→			}
   776→		}
   777→	}
   778→
   779→	@Override
   780→	public QueryIteratorKNN<PointEntryDist<T>> queryKNN(double[] center, int k) {
   781→		return new KNNIterator<>(this).reset(center, k);
   782→		//The kNN search above is consistently 2x faster so we use it instead of
   783→		//the Hjaltason/Samet algorithm below.
   784→		//return new CoverTreeQueryKnn<>(this, center, k, dist);
   785→	}
   786→
   787→	private void findNearestNeighbor(Node<T> p, double[] x, 
   788→			int k, ArrayList<PointDist<T>> candidates, double distPX) {
   789→//		Algorithm 1 Find nearest neighbor
   790→//		function findNearestNeighbor(cover tree p, query
   791→//		point x, nearest neighbor so far y)
   792→//		1: if d(p;x) < d(y;x) then
   793→//		2: y  p
   794→//		3: for each child q of p sorted by distance to x do
   795→//		4: if d(y;x) > d(y;q)-maxdist(q) then
   796→//		5: y findNearestNeighbor(q;x;y)
   797→//		6: return y
   798→		Point<T> nn = p.point();
   799→		if (candidates.size() < k) {
   800→			candidates.add(new PointDist<>(nn.point(), nn.value(), distPX));
   801→			candidates.sort(PointDist.COMPARATOR);
   802→		} else if (distPX < candidates.get(k-1).dist()) {
   803→			candidates.remove(k-1);
   804→			candidates.add(new PointDist<>(nn.point(), nn.value(), distPX));
   805→			candidates.sort(PointDist.COMPARATOR);
   806→		}
   807→
   808→		if (p.hasChildren()) {
   809→			ArrayList<Node<T>> children = p.getChildren();
   810→			for (int i = 0; i < children.size(); i++) {
   811→				Node<T> q = children.get(i);
   812→				double distCurrentWorst = candidates.get(candidates.size() - 1).dist();
   813→				
   814→				//Exclude children that are (compared to x) too close to the node or too far away
   815→				//to contain any useful points.
   816→				double distPQ = q.getDistanceToParent();
   817→				if (distPQ+q.maxdist(this) < distPX-distCurrentWorst
   818→						|| distPQ-q.maxdist(this)> distPX+distCurrentWorst) {
   819→					continue;
   820→				}
   821→				
   822→				//TODO cache d(y, x)
   823→	//			if (d(y, x) > (d(y, q.point()) - q.maxdist(this))) {
   824→	//				y = findNearestNeighbor(q, x, y);
   825→	//			}
   826→				double distQX = d(q.point(), x);
   827→				nDistKNN++;
   828→				if (distCurrentWorst > (distQX - q.maxdist(this))) {
   829→					findNearestNeighbor(q, x, k, candidates, distQX);
   830→				}
   831→			}
   832→		}
   833→	}
   834→
   835→	private static class KNNIterator<T> implements QueryIteratorKNN<PointEntryDist<T>> {
   836→
   837→		private final CoverTree<T> tree;
   838→		private final ArrayList<PointDist<T>> result = new ArrayList<>();
   839→		private Iterator<PointDist<T>> iter;
   840→		
   841→		public KNNIterator(CoverTree<T> tree) {
   842→			this.tree = tree;
   843→		}
   844→		
   845→		@Override
   846→		public boolean hasNext() {
   847→			return iter.hasNext();
   848→		}
   849→
   850→		@Override
   851→		public PointEntryDist<T> next() {
   852→			return iter.next();
   853→		}
   854→
   855→		@Override
   856→		public QueryIteratorKNN<PointEntryDist<T>> reset(double[] center, int k) {
   857→			result.clear();
   858→			if (tree.root != null) {
   859→				double distPX = tree.d(tree.root.point(), center);
   860→				tree.nDistKNN++;
   861→				tree.findNearestNeighbor(tree.root, center, k, result, distPX);
   862→			}
   863→			iter = result.iterator();
   864→			return this;
   865→		}	
   866→	}
   867→	
   868→	double d(Point<?> x, Point<?> y) {
   869→		return d(x, y.point());
   870→	}
   871→
   872→	double d(Node<?> x, Node<?> y) {
   873→		return d(x.point(), y.point().point());
   874→	}
   875→
   876→	private double d(Point<?> x, double[] p2) {
   877→		nDistCalc++;
   878→		return dist.dist(x.point(), p2);
   879→	}
   880→	
   881→	private double covdist(Node<?> p) {
   882→		return covDist(p.getLevel());
   883→	}
   884→
   885→	private double covDist(int level) {
   886→		//covdist(p) = 1:3level(p)
   887→		return Math.pow(BASE, level);
   888→	}
   889→
   890→	public boolean containsExact(double[] key) {
   891→		return queryExact(key) != null;
   892→	}
   893→
   894→	public void check() {
   895→		if (root != null) {
   896→			CTStats stats = new CTStats(this); 
   897→			getStats(root, stats);
   898→			if (stats.nEntries != nEntries) {
   899→				throw new IllegalStateException("nEntries: " + stats.nEntries + " / " + nEntries);
   900→			}
   901→		}
   902→	}
   903→	
   904→	private void getStats(Node<T> node, CTStats stats) {
   905→		stats.nEntries++;
   906→		stats.nNodes++;
   907→		stats.minLevel = Math.min(stats.minLevel, node.getLevel());
   908→		stats.maxLevel = Math.max(stats.maxLevel, node.getLevel());
   909→		stats.maxDepth = stats.maxLevel - stats.minLevel;
   910→		stats.sumLevel += node.getLevel();
   911→		
   912→		if (node.hasChildren()) {
   913→			double maxDist = -1;
   914→			stats.maxNodeSize = Math.max(stats.maxNodeSize, node.getChildren().size());
   915→			for (Node<T> c : node.getChildren()) {
   916→				double distToParent = d(node, c);
   917→				if (distToParent != c.getDistanceToParent()) {
   918→					throw new IllegalStateException(
   919→							"ParentDist: " + distToParent + " / " + c.getDistanceToParent());
   920→				}
   921→				if (node.getLevel() != c.getLevel() + 1) {
   922→					throw new IllegalStateException(
   923→							"Level: " + node.getLevel() + " / " + c.getLevel());
   924→				}
   925→				
   926→				getStats(c, stats);
   927→			}
   928→			
   929→			maxDist = getGlobalMaxDist(node); 
   930→			stats.sumMaxDist+=maxDist;
   931→
   932→			if (maxDist != node.maxdist(this)) {
   933→				throw new IllegalStateException(
   934→						"Maxdist: " + maxDist + " / " + node.maxdist(this) +
   935→						" Node:" + toStringNode(new StringBuilder(), node));
   936→			}
   937→			if (maxDist > covdist(node))  {
   938→				throw new IllegalStateException("Maxdist/maxdist()/CovDist: " + 
   939→						maxDist + " / " + node.maxdist(this) + " / " + covdist(node));
   940→			}
   941→		} else {
   942→			stats.nLeaf++;
   943→		}
   944→	}
   945→	
   946→	private double getGlobalMaxDist(Node<T> node) {
   947→		double currentMax = 0;
   948→		if (node.hasChildren()) {
   949→			for (Node<T> sub : node.getChildren()) {
   950→				currentMax = getGlobalMaxDist(node, sub, currentMax);
   951→			}
   952→		}
   953→		return currentMax;
   954→	}
   955→	
   956→	private double getGlobalMaxDist(Node<T> p, Node<T> node, double currentMax) {
   957→		double distOfThisNode = d(p, node);
   958→		currentMax = Math.max(currentMax, distOfThisNode);
   959→		if (node.hasChildren() && distOfThisNode + node.maxdist(this) > currentMax) {
   960→			for (Node<T> sub : node.getChildren()) {
   961→				currentMax = Math.max(currentMax, getGlobalMaxDist(p, sub, currentMax));
   962→			}
   963→		}
   964→		return currentMax;
   965→	}
   966→	
   967→	 public static class CTStats extends Stats {
   968→		double sumMaxDist = 0;
   969→		
   970→		CTStats(CoverTree<?> tree) {
   971→			super(tree.nDistCalc, tree.nDist1NN, tree.nDistKNN);
   972→		}
   973→		
   974→		@Override
   975→		public String toString() {
   976→			return super.toString() +
   977→					";sumMaxDist=" + sumMaxDist;
   978→		}
   979→	}
   980→
   981→	Node<T> getRoot() {
   982→		return root;
   983→	}
   984→	
   985→	@Override
   986→	public String toString() {
   987→		return this.getClass().getSimpleName() + 
   988→				";BASE=" + BASE +  
   989→				";NEAREST_ANCESTOR=" + NEAREST_ANCESTOR + 
   990→				";DistFn=" + PointDistanceFunction.getName(dist);
   991→	}
   992→
   993→}
