		size++;
		modCount++;
		if (root == null) {
			root = new Node<>(key, value, 0, defensiveKeyCopy);
			return;
		}
		Node<T> n = root;
		while ((n = n.getClosestNodeOrAddPoint(key, value, dims, defensiveKeyCopy)) != null) ;
